/* ──────────────────────────────────────────────────────────────────────────
   learnroman-sofia.js — „Sofía in London" · Zielsprache ENGLISCH
   Muttersprachen es + de (na/tr/teaser als {es, de}). Fester Inhalt, kein API-Call.
   Neutrales, internationales Englisch („tipo BBC", Leo 15.10.2026), britische
   Schreibung. Der englische Lernpfad ist amerikanisch → Dan (USA) bringt die
   US-Wörter, London die britischen; jedes Paar einmal, mit einem Lächeln.
   Aufbau wie learnroman-lukas.js: Teil I = A1-Szenen (lernpfad-daten-en.js a1.*),
   Teil II = A2, Epilog = englische Prosa ohne Brücke.
   Motor: proof of address → Bankkonto bis 25. Oktober.
   ────────────────────────────────────────────────────────────────────────── */
/* ──────────────────────────────────────────────────────────────────────────
   lr-parts/sofia-1.js — „Sofía in London" · Zielsprache Englisch
   TEIL I · FUNDAMENT · “The proof of address” — die zehn A1-Szenen
   Muttersprachen: es (castellano de España), de (Hochdeutsch).
   Englisch: neutral, britische Schreibweise; US-Wörter kommen von Dan
   (oder aus dem Lernpfad) und werden je einmal mit dem britischen Wort gepaart.
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_SOFIA = w.__LR_PARTS_SOFIA || {};
  function N(a, b) { return { na: { es: a, de: b } }; }
  function Z(z, a, b) { var o = { z: z }; if (a) o.tr = { es: a, de: b }; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, teaserA, teaserB, body) {
    return { level: level, n: n, thema: thema, title: title, teaser: { es: teaserA, de: teaserB }, body: body };
  }

  K.teil1 = [

  // ── Station 1 · TAXI ────────────────────────────────────────────────
  S("fundament", 1, "taxi", "Are you free?",
    "Sofía aterriza en Londres bajo la lluvia, y un correo de la editorial le pide tres palabras que no puede conseguir.",
    "Sofía landet im Londoner Regen, und eine Mail vom Verlag verlangt drei Wörter, die sie nicht beschaffen kann.",
  [
    N("Aeropuerto de Heathrow, Terminal 3. Un martes de octubre, las nueve de la noche. Fuera llueve. No mucho, pero sin parar, como si Londres llevara siglos ensayando.",
      "Flughafen Heathrow, Terminal 3. Ein Dienstag im Oktober, neun Uhr abends. Draußen regnet es. Nicht viel, aber ohne Pause, als würde London seit Jahrhunderten dafür proben."),
    N("Sofía Herrera, veintiséis años, diseñadora de libros, de un pueblo de Jalisco, arrastra una maleta verde enorme. Mañana empieza su primer trabajo en Europa, en una pequeña editorial de Bloomsbury.",
      "Sofía Herrera, sechsundzwanzig, Buchgestalterin aus einem Dorf in Jalisco, zieht einen riesigen grünen Koffer hinter sich her. Morgen beginnt ihr erster Job in Europa, in einem kleinen Verlag in Bloomsbury."),
    Z("PICCADILLY LINE: NO SERVICE THIS EVENING", "Línea Piccadilly: sin servicio esta noche", "Piccadilly Line: heute Abend kein Betrieb"),
    N("El metro, no. Sofía va a la parada de taxis: coches negros, altos y redondos, como sombreros antiguos con ruedas.",
      "Die U-Bahn also nicht. Sofía geht zum Taxistand: schwarze Autos, hoch und rund, wie alte Hüte auf Rädern."),
    Z("The first taxi is black. The driver has white hair and a big smile.", "El primer taxi es negro. El taxista tiene el pelo blanco y una gran sonrisa.", "Das erste Taxi ist schwarz. Der Fahrer hat weiße Haare und ein breites Lächeln."),
    N("En el avión ha ensayado una frase. Doce horas de vuelo para una frase corta.",
      "Im Flugzeug hat sie einen Satz geübt. Zwölf Stunden Flug für einen kurzen Satz."),
    Z("—Excuse me. Are you free?", "Perdone. ¿Está libre?", "Entschuldigung. Sind Sie frei?"),
    Z("—Evening! Yes, I'm free. Hop in.", "¡Buenas noches! Sí, estoy libre. Suba.", "’n Abend! Ja, ich bin frei. Steigen Sie ein."),
    Z("—Any bags?", "¿Lleva equipaje?", "Gepäck?"),
    Z("—Yes, one suitcase. It's very big.", "Sí, una maleta. Es muy grande.", "Ja, einen Koffer. Er ist sehr groß."),
    Z("—Big and green. Like a bus.", "Grande y verde. Como un autobús.", "Groß und grün. Wie ein Bus."),
    N("El móvil vibra. Un mensaje de Dan, el compañero de piso estadounidense. Todavía no lo conoce en persona, pero le escribe como si fueran amigos desde el colegio.",
      "Das Handy vibriert. Eine Nachricht von Dan, dem amerikanischen Mitbewohner. Sie kennt ihn noch nicht persönlich, aber er schreibt, als wären sie seit der Schule befreundet."),
    Z("DAN: Take a cab!! Put the suitcase in the trunk!", "DAN: ¡Coge un taxi! ¡Mete la maleta en el maletero!", "DAN: Nimm ein Taxi! Pack den Koffer in den Kofferraum!"),
    Z("—The trunk, please?", "¿El maletero, por favor?", "Den Kofferraum, bitte?"),
    Z("—The boot, love. In London, it's the boot.", "El maletero, cielo. En Londres se dice «boot».", "Den Kofferraum, Schätzchen. In London heißt das »boot«."),
    N("Boot. Bota. Sofía no ve ninguna bota. El taxista se ríe y abre la puerta de atrás: los taxis negros no tienen maletero para maletas. Ni «trunk» ni «boot». El equipaje viaja dentro, con el pasajero, como una tía que no quiere quedarse sola.",
      "Boot. Stiefel. Sofía sieht keinen Stiefel. Der Fahrer lacht und öffnet die hintere Tür: Die schwarzen Taxis haben keinen Kofferraum für Koffer. Weder »trunk« noch »boot«. Das Gepäck fährt innen mit, beim Fahrgast, wie eine Tante, die nicht allein bleiben will."),
    Z("The suitcase sits next to Sofía. It is wet. She is wet too.", "La maleta va sentada al lado de Sofía. Está mojada. Ella también.", "Der Koffer sitzt neben Sofía. Er ist nass. Sie auch."),
    Z("—Where to, love?", "¿Adónde, cielo?", "Wohin, Schätzchen?"),
    N("Love. Cielo. ¿Así le habla un taxista a una desconocida? En Londres, por lo visto, sí.",
      "Love. Schätzchen. Spricht ein Taxifahrer so mit einer Fremden? In London offenbar schon."),
    Z("—To this address, please.", "A esta dirección, por favor.", "Zu dieser Adresse, bitte."),
    Z("—Islington?", "¿Islington?", "Islington?"),
    Z("—No. Kentish Town.", "No. Kentish Town.", "Nein. Kentish Town."),
    Z("—Kentish Town. Lovely. I'm Del, by the way.", "Kentish Town. Estupendo. Por cierto, soy Del.", "Kentish Town. Schön. Ich bin übrigens Del."),
    Z("—I'm Sofía. I'm from Mexico.", "Soy Sofía. Soy de México.", "Ich bin Sofía. Ich komme aus Mexiko."),
    N("Autopista, luces rojas, limpiaparabrisas. Del habla de fútbol, de su nieta, de un primo en Benidorm. Sofía entiende «Benidorm». Entonces llega un correo de Recursos Humanos.",
      "Autobahn, rote Lichter, Scheibenwischer. Del redet über Fußball, über seine Enkelin, über einen Cousin in Benidorm. Sofía versteht »Benidorm«. Dann kommt eine Mail der Personalabteilung."),
    N("«Para cobrar tu primer sueldo el 31 de octubre necesitamos tu cuenta bancaria británica antes del día 25. El banco te pedirá un justificante de domicilio (proof of address).»",
      "»Damit du dein erstes Gehalt am 31. Oktober bekommst, brauchen wir bis zum 25. dein britisches Bankkonto. Die Bank wird einen Wohnsitznachweis verlangen (proof of address).«"),
    Z("Proof of address.", "Justificante de domicilio.", "Wohnsitznachweis."),
    N("Tres palabras. Ninguna difícil. Juntas, un misterio.",
      "Drei Wörter. Keins davon schwer. Zusammen ein Rätsel."),
    Z("—Del? What is “proof of address”?", "Del, ¿qué es un «proof of address»?", "Del, was ist ein »proof of address«?"),
    Z("—Paper, love. A letter or a contract, with your name and address. Welcome to England.", "Papeles, cielo. Una carta o un contrato, con tu nombre y tu dirección. Bienvenida a Inglaterra.", "Papierkram, Schätzchen. Ein Brief oder ein Vertrag, mit Namen und Adresse. Willkommen in England."),
    N("Un papel con su dirección, para tener cuenta. Una cuenta, para tener sueldo. Pero Sofía todavía no tiene dirección. Es un círculo, y ella está fuera.",
      "Ein Papier mit ihrer Adresse, um ein Konto zu bekommen. Ein Konto, um ein Gehalt zu bekommen. Aber Sofía hat noch keine Adresse. Es ist ein Kreis, und sie steht draußen."),
    Z("The streets are dark and wet. The houses are small and all the same.", "Las calles están oscuras y mojadas. Las casas son pequeñas y todas iguales.", "Die Straßen sind dunkel und nass. Die Häuser sind klein und alle gleich."),
    Z("—Can you pull over here, please? How much is it?", "¿Puede parar aquí, por favor? ¿Cuánto es?", "Können Sie bitte hier anhalten? Was macht das?"),
    Z("—Eighty-eight pounds, love.", "Ochenta y ocho libras, cielo.", "Achtundachtzig Pfund, Schätzchen."),
    N("Ochenta y ocho. Sofía empieza a calcularlo en pesos y prefiere no terminar. Le da cuatro billetes de veinte y uno de diez, nuevecitos.",
      "Achtundachtzig. Sofía fängt an, es in Pesos umzurechnen, und lässt es lieber. Sie gibt ihm vier Zwanziger und einen Zehner, ganz neu."),
    Z("—Keep the change.", "Quédese con el cambio.", "Behalten Sie den Rest."),
    Z("—Cheers, love. Good luck with your proof of address!", "Gracias, cielo. ¡Suerte con el justificante de domicilio!", "Danke, Schätzchen. Viel Glück mit dem Wohnsitznachweis!"),
    N("Cheers. ¿No era eso para brindar? El taxi negro desaparece en la lluvia como un escarabajo.",
      "Cheers. Sagt man das nicht beim Anstoßen? Das schwarze Taxi verschwindet im Regen wie ein Käfer."),
    N("En el primer piso de una casa de ladrillo se abre una ventana. Una mujer con gafas grandes y trenza negra saluda con los dos brazos.",
      "Im ersten Stock eines Backsteinhauses geht ein Fenster auf. Eine Frau mit großer Brille und schwarzem Zopf winkt mit beiden Armen."),
    Z("—Sofía! Hi! I'm Priya! Wait, I'm coming down!", "¡Sofía! ¡Hola! ¡Soy Priya! ¡Espera, ya bajo!", "Sofía! Hallo! Ich bin Priya! Warte, ich komme runter!"),
    N("Priya Nair, de Bangalore, programadora. Por teléfono le dijo: «En este piso se habla inglés. Despacio, si quieres. Pero inglés».",
      "Priya Nair, aus Bengaluru, Programmiererin. Am Telefon hat sie gesagt: »In dieser Wohnung wird Englisch gesprochen. Langsam, wenn du willst. Aber Englisch.«"),
    N("Sofía mira la maleta verde, la lluvia, el correo. Quedan diecisiete días hasta el 25.",
      "Sofía schaut auf den grünen Koffer, auf den Regen, auf die Mail. Noch siebzehn Tage bis zum 25."),
    Z("Proof of address.")
  ]),

  // ── Station 2 · CAFÉ ────────────────────────────────────────────────
  S("fundament", 2, "cafe", "Eat in or take away?",
    "El primer café en el local de la señora Georgiou, y Priya dibuja en una servilleta el camino hasta una firma en Brighton.",
    "Der erste Kaffee bei Mrs Georgiou, und Priya zeichnet auf eine Serviette den Weg zu einer Unterschrift in Brighton.",
  [
    N("A la mañana siguiente, Sofía encuentra la cocina llena de cajas de té. Té negro, té verde, té de jengibre, té de algo que parece hierba del jardín. Café, ni uno.",
      "Am nächsten Morgen findet Sofía eine Küche voller Teeschachteln. Schwarzer Tee, grüner Tee, Ingwertee, Tee aus etwas, das wie Gartengras aussieht. Kaffee: keiner."),
    Z("—Good morning! Tea?", "¡Buenos días! ¿Té?", "Guten Morgen! Tee?"),
    Z("—Coffee, please. I'm from Mexico.", "Café, por favor. Soy de México.", "Kaffee, bitte. Ich komme aus Mexiko."),
    Z("—Then we go to Mrs Georgiou. Come on.", "Entonces vamos a ver a la señora Georgiou. Vamos.", "Dann gehen wir zu Mrs Georgiou. Komm."),
    Z("Dan is still asleep. He is a barista in an expensive café in Camden.", "Dan todavía duerme. Es barista en un café caro de Camden.", "Dan schläft noch. Er ist Barista in einem teuren Café in Camden."),
    N("Allí un capuchino cuesta casi cinco libras. «Café de verdad a precio honrado», dice Priya, «en la esquina».",
      "Dort kostet ein Cappuccino fast fünf Pfund. »Echter Kaffee zu einem ehrlichen Preis«, sagt Priya, »an der Ecke.«"),
    Z("GEORGIOU'S CAFÉ — SINCE 1987", "Café Georgiou — desde 1987", "Café Georgiou — seit 1987"),
    N("Un local estrecho, mesas de fórmica, la foto de un pueblo blanco junto al mar. Detrás de la barra, Eleni Georgiou, de Chipre: pequeña, pelo gris, ojos que lo ven todo.",
      "Ein schmaler Raum, Resopaltische, das Foto eines weißen Dorfes am Meer. Hinter der Theke Eleni Georgiou, aus Zypern: klein, graue Haare, Augen, die alles sehen."),
    Z("Five people stand in a line. Nobody speaks.", "Cinco personas esperan en fila. Nadie habla.", "Fünf Leute stehen in einer Reihe. Niemand spricht."),
    N("Sofía no ve la fila. Va directa a la barra. Un señor con paraguas tose. Muy bajito.",
      "Sofía sieht die Schlange nicht. Sie geht direkt zur Theke. Ein Herr mit Regenschirm hustet. Ganz leise."),
    Z("—The queue, darling. It starts there.", "La cola, querida. Empieza allí.", "Die Schlange, meine Liebe. Sie fängt dort an."),
    N("Sofía se pone al final de la fila, roja como un chile. Priya le susurra: «La cola es sagrada. Aquí puedes insultar al rey, pero no colarte».",
      "Sofía stellt sich hinten an, rot wie eine Chilischote. Priya flüstert: »Die Schlange ist heilig. Hier darfst du den König beleidigen, aber nicht vordrängeln.«"),
    Z("—Hi there. What can I get you?", "Hola. ¿Qué te pongo?", "Hallo. Was darf’s sein?"),
    Z("—A coffee, please.", "Un café, por favor.", "Einen Kaffee, bitte."),
    Z("—Eat in or take away?", "¿Para tomar aquí o para llevar?", "Zum Hierbleiben oder zum Mitnehmen?"),
    N("Sofía conoce la pregunta. Su aplicación de inglés es americana y la pregunta allí suena distinta. Responde con lo que sabe.",
      "Sofía kennt die Frage. Ihre Englisch-App ist amerikanisch, und dort klingt die Frage anders. Sie antwortet mit dem, was sie kann."),
    Z("—For here, please.", "Para tomar aquí, por favor.", "Zum Hiertrinken, bitte."),
    Z("—Eat in. Good. Milk? Sugar?", "Para tomar aquí. Bien. ¿Leche? ¿Azúcar?", "Hier also. Gut. Milch? Zucker?"),
    Z("—Milk, please. No sugar.", "Leche, por favor. Sin azúcar.", "Milch, bitte. Kein Zucker."),
    Z("—Coming right up. Anything else?", "Ahora mismo. ¿Algo más?", "Kommt sofort. Sonst noch etwas?"),
    Z("—No, thanks. How much do I owe you?", "No, gracias. ¿Cuánto le debo?", "Nein, danke. Was schulde ich Ihnen?"),
    Z("—Three fifty.", "Tres cincuenta.", "Drei fünfzig."),
    Z("Sofía gives her five pounds. She gets one pound fifty back.", "Sofía le da cinco libras. Le devuelven una libra con cincuenta.", "Sofía gibt ihr fünf Pfund. Sie bekommt ein Pfund fünfzig zurück."),
    Z("—And for me, a tea with milk, please.", "Y para mí, un té con leche, por favor.", "Und für mich einen Tee mit Milch, bitte."),
    N("Té con leche. Sofía la mira como si hubiera pedido sopa con mermelada. En su casa, el té es de manzanilla y nadie le echa leche.",
      "Tee mit Milch. Sofía sieht sie an, als hätte sie Suppe mit Marmelade bestellt. Bei ihr zu Hause ist Tee Kamillentee, und niemand gießt Milch hinein."),
    Z("—Milk in tea? Really?", "¿Leche en el té? ¿En serio?", "Milch in den Tee? Wirklich?"),
    Z("—Really. In India too. You will see.", "En serio. En la India también. Ya verás.", "Wirklich. In Indien auch. Du wirst sehen."),
    N("Se sientan junto a la ventana. Priya saca un bolígrafo y escribe en una servilleta, con letra de programadora: cada cosa en su línea.",
      "Sie setzen sich ans Fenster. Priya zieht einen Kuli heraus und schreibt auf eine Serviette, in Programmiererinnen-Schrift: jedes Ding in seiner Zeile."),
    Z("1. Passport. 2. Bank appointment. 3. Proof of address.", "1. Pasaporte. 2. Cita en el banco. 3. Justificante de domicilio.", "1. Pass. 2. Banktermin. 3. Wohnsitznachweis."),
    N("La cita, Priya la busca en el móvil: solo queda una libre antes del 25. La reserva sin preguntar.",
      "Den Termin sucht Priya auf dem Handy: Vor dem 25. gibt es nur noch einen freien. Sie bucht ihn, ohne zu fragen."),
    Z("—Thursday the twenty-fourth. Nine thirty. Done.", "Jueves 24. A las nueve y media. Hecho.", "Donnerstag, der Vierundzwanzigste. Halb zehn. Erledigt."),
    N("Lo difícil es el número tres: el contrato de alquiler, el tenancy agreement, firmado por el casero. El casero es el capitán Desmond Clarke, setenta y nueve años, marino retirado, de Brighton. «No se fía del correo electrónico», dice Priya, «ni de la gente que habla rápido».",
      "Das Schwierige ist Nummer drei: der Mietvertrag, das tenancy agreement, unterschrieben vom Vermieter. Der Vermieter ist Kapitän Desmond Clarke, neunundsiebzig, pensionierter Seemann, aus Brighton. »Er traut keinen E-Mails«, sagt Priya, »und keinen Leuten, die schnell reden.«"),
    Z("—So I need his signature.", "Entonces necesito su firma.", "Also brauche ich seine Unterschrift."),
    Z("—Yes. On paper. With a pen.", "Sí. En papel. Con bolígrafo.", "Ja. Auf Papier. Mit einem Stift."),
    N("En Bangalore, explica Priya, todas las oficinas terminan sus cartas igual: «Please do the needful». Haga lo necesario. Nadie sabe qué es lo necesario. Por eso funciona.",
      "In Bengaluru, erklärt Priya, enden alle Behördenbriefe gleich: »Please do the needful.« Tun Sie das Nötige. Niemand weiß, was das Nötige ist. Deshalb funktioniert es."),
    N("La señora Georgiou trae el café. Es fuerte, caliente y bueno. No sonríe. Pero deja junto a la taza una galleta pequeña que nadie ha pedido.",
      "Mrs Georgiou bringt den Kaffee. Er ist stark, heiß und gut. Sie lächelt nicht. Aber neben die Tasse legt sie einen kleinen Keks, den niemand bestellt hat."),
    N("Esa noche Dan, por fin despierto, escucha la historia de la cola y aplaude.",
      "An diesem Abend hört Dan, endlich wach, die Geschichte von der Schlange und klatscht."),
    Z("—“Eat in or take away?” In Ohio we say: “For here or to go?”", "«¿Para tomar aquí o para llevar?». En Ohio decimos: «For here or to go?».", "»Eat in or take away?« In Ohio sagen wir: »For here or to go?«"),
    N("Dos idiomas por el precio de uno, piensa Sofía. Y ninguno es el suyo.",
      "Zwei Sprachen zum Preis von einer, denkt Sofía. Und keine davon ist ihre."),
    Z("One coffee. Two Englishes.", "Un café. Dos ingleses.", "Ein Kaffee. Zweierlei Englisch.")
  ]),

  // ── Station 3 · EINKAUFEN ───────────────────────────────────────────
  S("fundament", 3, "einkaufen", "A pound of cheese",
    "En Borough Market, una libra puede ser dinero o peso, y un quesero resulta haber navegado con el capitán Clarke.",
    "Auf dem Borough Market kann ein Pfund Geld oder Gewicht sein, und ein Käsehändler ist einmal mit Kapitän Clarke zur See gefahren.",
  [
    N("Sábado. Dan ha decidido que Sofía necesita «ver Londres de verdad», y para Dan Londres de verdad es un mercado con comida.",
      "Samstag. Dan hat beschlossen, dass Sofía »das echte London« sehen muss, und für Dan ist das echte London ein Markt mit Essen."),
    N("Dan Kowalski, de Ohio, músico y barista, veintisiete años, gorra roja, habla tan alto como si todos los londinenses estuvieran un poco sordos. Es simpático. Es incansable. Y usa siempre la palabra americana.",
      "Dan Kowalski, aus Ohio, Musiker und Barista, siebenundzwanzig, rote Kappe, redet so laut, als wären alle Londoner ein bisschen schwerhörig. Er ist nett. Er ist unermüdlich. Und er benutzt immer das amerikanische Wort."),
    Z("Borough Market is under a railway bridge. It is full of people, colours and smells.", "Borough Market está debajo de un puente del tren. Está lleno de gente, colores y olores.", "Der Borough Market liegt unter einer Eisenbahnbrücke. Er ist voller Menschen, Farben und Gerüche."),
    N("Pan que todavía humea, ostras sobre hielo, setas que parecen orejas. Un tren pasa por encima y nadie levanta la cabeza.",
      "Brot, das noch dampft, Austern auf Eis, Pilze, die wie Ohren aussehen. Oben fährt ein Zug vorbei, und niemand schaut auf."),
    Z("—Hi! What would you like?", "¡Hola! ¿Qué te pongo?", "Hallo! Was darf’s sein?"),
    Z("—Just these apples, please.", "Solo estas manzanas, por favor.", "Nur diese Äpfel, bitte."),
    Z("—Four apples. Two pounds.", "Cuatro manzanas. Dos libras.", "Vier Äpfel. Zwei Pfund."),
    N("Después, el queso. Un puesto pequeño con quesos redondos como ruedas de carreta. Detrás, un hombre alto con bata blanca y una gorra azul de marinero: el señor Ade. En la pared, una foto vieja de un barco.",
      "Dann der Käse. Ein kleiner Stand mit Käselaiben, rund wie Wagenräder. Dahinter ein großer Mann in weißem Kittel und blauer Seemannsmütze: Mr Ade. An der Wand hängt ein altes Foto von einem Schiff."),
    Z("—Good morning. What can I do for you?", "Buenos días. ¿Qué le pongo?", "Guten Morgen. Was darf ich Ihnen geben?"),
    N("Antes de que Sofía abra la boca, Dan contesta por ella. Con entusiasmo. Con acento de Ohio.",
      "Bevor Sofía den Mund aufmacht, antwortet Dan für sie. Begeistert. Mit Ohio-Akzent."),
    Z("—A pound of cheese, please!", "¡Una libra de queso, por favor!", "Ein Pfund Käse, bitte!"),
    Z("—A pound in weight or a pound in money?", "¿Una libra de peso o una libra de dinero?", "Ein Pfund Gewicht oder ein Pfund Geld?"),
    N("Dan se queda callado por primera vez en el día. El señor Ade explica, despacio: en Gran Bretaña el queso se vende en gramos, pero la gente mayor todavía piensa en libras. Y una libra en dinero da para un trocito así. Pone dos dedos muy juntos.",
      "Dan ist zum ersten Mal an diesem Tag still. Mr Ade erklärt, langsam: In Großbritannien verkauft man Käse in Gramm, aber ältere Leute denken noch in Pfund. Und für ein Pfund in Geld gibt es ein Stückchen so groß. Er hält zwei Finger dicht aneinander."),
    Z("—A small piece, please. That one.", "Un trozo pequeño, por favor. Ese.", "Ein kleines Stück, bitte. Das da."),
    Z("—Good choice. Two hundred grams. That's eight forty-nine.", "Buena elección. Doscientos gramos. Son ocho cuarenta y nueve.", "Gute Wahl. Zweihundert Gramm. Das macht acht neunundvierzig."),
    Z("—Can I pay by card?", "¿Puedo pagar con tarjeta?", "Kann ich mit Karte zahlen?"),
    Z("—Cash or card, as you like.", "Efectivo o tarjeta, como quiera.", "Bar oder Karte, wie Sie möchten."),
    Z("—Card, please.", "Con tarjeta, por favor.", "Mit Karte, bitte."),
    Z("—Do you need a bag? And the receipt?", "¿Necesita bolsa? ¿Y el tique?", "Brauchen Sie eine Tüte? Und den Kassenbon?"),
    Z("—No bag, thanks. I have a bag.", "Bolsa no, gracias. Tengo una.", "Keine Tüte, danke. Ich habe eine Tasche."),
    N("Sofía abre el bolso para guardar el queso. Encima de todo, en una carpeta de plástico, está el contrato de alquiler sin firmar. El señor Ade ve el nombre en la primera página y se inclina hacia delante.",
      "Sofía öffnet die Tasche, um den Käse zu verstauen. Ganz oben, in einer Plastikmappe, liegt der Mietvertrag, noch ohne Unterschrift. Mr Ade sieht den Namen auf der ersten Seite und beugt sich vor."),
    Z("—Clarke? Captain Desmond Clarke? From Brighton?", "¿Clarke? ¿El capitán Desmond Clarke? ¿De Brighton?", "Clarke? Kapitän Desmond Clarke? Aus Brighton?"),
    Z("—Yes. He is my landlord. Do you know him?", "Sí. Es mi casero. ¿Lo conoce?", "Ja. Er ist mein Vermieter. Kennen Sie ihn?"),
    Z("—Know him? I sailed with him. Lagos to Liverpool, nineteen eighty-one. That is his ship.", "¿Que si lo conozco? Navegué con él. De Lagos a Liverpool, en mil novecientos ochenta y uno. Ese es su barco.", "Ob ich ihn kenne? Ich bin mit ihm gefahren. Von Lagos nach Liverpool, neunzehnhunderteinundachtzig. Das ist sein Schiff."),
    N("Señala la foto de la pared. Un barco gris, un mar gris y, en la cubierta, un hombre joven con una barba enorme. El señor Ade se ríe con todo el cuerpo.",
      "Er zeigt auf das Foto an der Wand. Ein graues Schiff, ein graues Meer und an Deck ein junger Mann mit einem riesigen Bart. Mr Ade lacht mit dem ganzen Körper."),
    N("Sofía le cuenta el problema: el banco, la firma, el capitán que no lee correos. El señor Ade escucha, asiente, y envuelve en papel un trozo grande de un queso azul y fuerte.",
      "Sofía erzählt ihm das Problem: die Bank, die Unterschrift, der Kapitän, der keine Mails liest. Mr Ade hört zu, nickt und wickelt ein großes Stück eines kräftigen Blauschimmelkäses in Papier."),
    Z("—Stilton. For the captain. He loves it. It is a present, no money.", "Stilton. Para el capitán. Le encanta. Es un regalo, no se paga.", "Stilton. Für den Kapitän. Er liebt ihn. Das ist ein Geschenk, kostet nichts."),
    Z("—Thank you so much!", "¡Muchísimas gracias!", "Vielen, vielen Dank!"),
    Z("—And call him at six. Not five, not seven. At six he answers the phone.", "Y llámelo a las seis. Ni a las cinco ni a las siete. A las seis contesta el teléfono.", "Und rufen Sie ihn um sechs an. Nicht um fünf, nicht um sieben. Um sechs geht er ans Telefon."),
    Z("—Have a good one!", "¡Que vaya bien!", "Mach’s gut!"),
    N("A las seis en punto, sentada en la escalera de casa, Sofía marca el número. Un tono. Dos. Una voz grave, como de radio antigua.",
      "Um Punkt sechs, auf der Treppe vor dem Haus, wählt Sofía die Nummer. Ein Freizeichen. Zwei. Eine tiefe Stimme, wie aus einem alten Radio."),
    Z("—Clarke.", "Clarke.", "Clarke."),
    Z("—Hello, Captain Clarke. My name is Sofía. I live in your flat. Mr Ade says hello.", "Hola, capitán Clarke. Me llamo Sofía. Vivo en su piso. El señor Ade le manda saludos.", "Hallo, Kapitän Clarke. Ich heiße Sofía. Ich wohne in Ihrer Wohnung. Mr Ade lässt grüßen."),
    Z("—Ade! Ha! … I don't sign papers on the telephone, young lady. Come to Brighton. Saturday. One o'clock.", "¡Ade! ¡Ja! … Yo no firmo papeles por teléfono, señorita. Venga a Brighton. El sábado. A la una.", "Ade! Ha! … Ich unterschreibe keine Papiere am Telefon, junge Dame. Kommen Sie nach Brighton. Samstag. Ein Uhr."),
    N("Y cuelga. Sin adiós. Sofía se queda mirando el móvil. En la bolsa, el Stilton empieza a oler a barco.",
      "Und legt auf. Ohne Tschüss. Sofía starrt auf das Handy. In der Tasche fängt der Stilton an, nach Schiff zu riechen."),
    Z("Saturday. One o'clock. Brighton.", "Sábado. A la una. Brighton.", "Samstag. Ein Uhr. Brighton.")
  ]),

  // ── Station 4 · WEGBESCHREIBUNG ─────────────────────────────────────
  S("fundament", 4, "wegbeschreibung", "Two blocks?",
    "Móvil sin batería, unas indicaciones de Ohio y una ciudad que no tiene manzanas: Sofía busca el banco.",
    "Leerer Akku, eine Wegbeschreibung aus Ohio und eine Stadt ohne Blocks: Sofía sucht die Bank.",
  [
    N("Martes, una semana después de llegar. Sofía ya trabaja en la editorial: cuatro personas, mil libros y un gato que se llama Gutenberg.",
      "Dienstag, eine Woche nach der Ankunft. Sofía arbeitet schon im Verlag: vier Leute, tausend Bücher und eine Katze namens Gutenberg."),
    Z("At lunchtime, she walks to the bank near Trafalgar Square. She has questions for Thursday.", "A la hora de comer va andando al banco, cerca de Trafalgar Square. Tiene preguntas para el jueves.", "In der Mittagspause geht sie zu Fuß zur Bank am Trafalgar Square. Sie hat Fragen für Donnerstag."),
    Z("Her phone says: one per cent. Then it says nothing.", "El móvil dice: uno por ciento. Luego ya no dice nada.", "Das Handy sagt: ein Prozent. Dann sagt es nichts mehr."),
    N("Sin mapa. Pero tiene un plan B: por la mañana Dan le escribió el camino en un papel, con muchas flechas y un dibujo de un león.",
      "Keine Karte. Aber sie hat einen Plan B: Am Morgen hat Dan ihr den Weg auf einen Zettel geschrieben, mit vielen Pfeilen und einer Zeichnung von einem Löwen."),
    Z("“Go straight for two blocks, then turn left. You can't miss it! — Dan”", "«Sigue recto dos manzanas y luego gira a la izquierda. ¡No tiene pérdida! — Dan»", "»Geh zwei Blocks geradeaus, dann links abbiegen. Nicht zu verfehlen! — Dan«"),
    N("Dos manzanas. Pero Londres no tiene manzanas. Tiene calles que se tuercen, se cruzan, cambian de nombre a mitad de camino. Sofía cuenta una calle, luego otra, luego no sabe si aquello era una calle o un callejón.",
      "Zwei Blocks. Aber London hat keine Blocks. Es hat Straßen, die sich krümmen, sich kreuzen und mitten auf dem Weg den Namen wechseln. Sofía zählt eine Straße, dann noch eine, dann weiß sie nicht, ob das eine Straße war oder eine Gasse."),
    N("Cerca de un semáforo, una señora con un perro salchicha y un abrigo amarillo espera para cruzar. Sofía se acerca. Sin querer, le pisa el pie.",
      "An einer Ampel wartet eine Dame mit einem Dackel und einem gelben Mantel. Sofía geht auf sie zu. Aus Versehen tritt sie ihr auf den Fuß."),
    Z("—Oh! Sorry!", "¡Ay! ¡Perdón!", "Oh! Entschuldigung!"),
    Z("—No, no, sorry! My fault!", "No, no, ¡perdón! ¡Ha sido culpa mía!", "Nein, nein, Entschuldigung! Meine Schuld!"),
    N("La señora pide perdón porque Sofía le ha pisado el pie. Sofía lo apunta mentalmente: en Inglaterra, «sorry» no es una disculpa. Es un saludo.",
      "Die Dame entschuldigt sich, weil Sofía ihr auf den Fuß getreten ist. Sofía merkt es sich: In England ist »sorry« keine Entschuldigung. Es ist eine Begrüßung."),
    Z("—Are you looking for something?", "¿Busca algo?", "Suchen Sie etwas?"),
    Z("—Yes. Excuse me, where's Trafalgar Square?", "Sí. Perdone, ¿dónde está Trafalgar Square?", "Ja. Entschuldigung, wo ist der Trafalgar Square?"),
    Z("—Go straight on, past the traffic lights. Then turn left at the corner.", "Siga recto, pase el semáforo. Luego gire a la izquierda en la esquina.", "Gehen Sie geradeaus, an der Ampel vorbei. Dann an der Ecke links."),
    Z("—Two blocks?", "¿Dos manzanas?", "Zwei Blocks?"),
    N("La señora se ríe tanto que el perro ladra.",
      "Die Dame lacht so sehr, dass der Hund bellt."),
    Z("—Blocks? This is London, not New York. We don't have blocks. We have streets. Two streets, yes.", "¿Manzanas? Esto es Londres, no Nueva York. Aquí no hay manzanas. Hay calles. Dos calles, sí.", "Blocks? Das hier ist London, nicht New York. Wir haben keine Blocks. Wir haben Straßen. Zwei Straßen, ja."),
    Z("—Is it far?", "¿Está lejos?", "Ist es weit?"),
    Z("—No, it's nearby. About a five-minute walk.", "No, está cerca. A unos cinco minutos a pie.", "Nein, es ist in der Nähe. Ungefähr fünf Minuten zu Fuß."),
    Z("—Thank you so much! Sorry!", "¡Muchísimas gracias! ¡Perdón!", "Vielen, vielen Dank! Entschuldigung!"),
    Z("—Sorry? For what? Ha! You are almost English!", "¿Perdón? ¿Por qué? ¡Ja! ¡Ya es usted casi inglesa!", "Entschuldigung? Wofür? Ha! Sie sind ja fast Engländerin!"),
    Z("She goes straight on, past the lights, then left at the corner. And there it is: a big square, fountains, four black lions and a thousand pigeons.", "Sigue recto, pasa el semáforo y gira a la izquierda en la esquina. Y ahí está: una plaza grande, fuentes, cuatro leones negros y mil palomas.", "Sie geht geradeaus, an der Ampel vorbei, dann an der Ecke links. Und da ist er: ein großer Platz, Brunnen, vier schwarze Löwen und tausend Tauben."),
    N("En el centro, una columna altísima con un señor arriba, que tampoco sabe dónde está el banco.",
      "In der Mitte eine sehr hohe Säule mit einem Herrn obendrauf, der auch nicht weiß, wo die Bank ist."),
    Z("The bank is across from the square, next to a bookshop.", "El banco está enfrente de la plaza, al lado de una librería.", "Die Bank ist gegenüber vom Platz, neben einer Buchhandlung."),
    N("Dentro hace calor y huele a moqueta. Un empleado joven con corbata morada la atiende sin cita. Es amable. Es exacto. Es una lista con piernas.",
      "Drinnen ist es warm und riecht nach Teppichboden. Ein junger Angestellter mit lila Krawatte bedient sie ohne Termin. Er ist freundlich. Er ist genau. Er ist eine Liste mit Beinen."),
    Z("—On Thursday, bring your passport. And proof of address.", "El jueves traiga el pasaporte. Y un justificante de domicilio.", "Am Donnerstag bringen Sie Ihren Pass mit. Und einen Wohnsitznachweis."),
    Z("—My tenancy agreement?", "¿Mi contrato de alquiler?", "Meinen Mietvertrag?"),
    Z("—Yes. Signed by the landlord. On paper. Not a copy, not an e-mail.", "Sí. Firmado por el casero. En papel. Ni una copia ni un correo.", "Ja. Vom Vermieter unterschrieben. Auf Papier. Keine Kopie, keine E-Mail."),
    N("Nada que Sofía no supiera ya. Pero oírlo de una corbata morada lo hace oficial. Sale a la plaza y se sienta junto a un león. Una paloma se le acerca y la mira, como esperando que pida perdón también a ella.",
      "Nichts, was Sofía nicht schon wusste. Aber von einer lila Krawatte gehört, ist es offiziell. Sie geht auf den Platz und setzt sich neben einen Löwen. Eine Taube kommt näher und schaut sie an, als warte sie darauf, dass Sofía sich auch bei ihr entschuldigt."),
    Z("—Sorry.", "Perdón.", "Entschuldigung."),
    N("Una semana en Londres. Y ya.",
      "Eine Woche in London. Und schon ist es so weit.")
  ]),

  // ── Station 5 · BAHNHOF ─────────────────────────────────────────────
  S("fundament", 5, "bahnhof", "Single or return?",
    "Victoria Station, un billete de ida y vuelta y un queso que viaja en primera fila: Sofía va hacia el mar.",
    "Victoria Station, eine Rückfahrkarte und ein Käse, der in der ersten Reihe mitfährt: Sofía fährt ans Meer.",
  [
    N("Sábado, 19 de octubre. En la mochila: el pasaporte, el contrato en su carpeta de plástico y el Stilton, envuelto en tres bolsas. Tres bolsas no bastan.",
      "Samstag, 19. Oktober. Im Rucksack: der Pass, der Vertrag in seiner Plastikmappe und der Stilton, eingewickelt in drei Tüten. Drei Tüten reichen nicht."),
    Z("In the Underground, a voice says: “Mind the gap.”", "En el metro, una voz dice: «Cuidado con el hueco».", "In der U-Bahn sagt eine Stimme: »Achten Sie auf die Lücke.«"),
    N("El hueco entre el vagón y el andén es pequeño, pero la voz lo dice como si fuera un abismo. Una ciudad que te avisa de los peligros pequeños.",
      "Der Spalt zwischen Wagen und Bahnsteig ist klein, aber die Stimme sagt es, als wäre es ein Abgrund. Eine Stadt, die einen vor den kleinen Gefahren warnt."),
    Z("Victoria Station is big and loud. There are trains, shops and a big clock.", "La estación Victoria es grande y ruidosa. Hay trenes, tiendas y un reloj grande.", "Victoria Station ist groß und laut. Es gibt Züge, Geschäfte und eine große Uhr."),
    Z("There are ticket machines, but Sofía wants to talk to a person. She goes to the ticket office. There is a queue. This time, she sees it.", "Hay máquinas de billetes, pero Sofía quiere hablar con una persona. Va a la taquilla. Hay cola. Esta vez la ve.", "Es gibt Fahrkartenautomaten, aber Sofía will mit einem Menschen sprechen. Sie geht zum Schalter. Es gibt eine Schlange. Diesmal sieht sie sie."),
    N("Se pone al final. Nadie tose.",
      "Sie stellt sich hinten an. Niemand hustet."),
    Z("—Next, please. What can I do for you?", "El siguiente, por favor. ¿Qué desea?", "Der Nächste, bitte. Was kann ich für Sie tun?"),
    Z("—One ticket to Brighton, please.", "Un billete para Brighton, por favor.", "Eine Fahrkarte nach Brighton, bitte."),
    Z("—Single or return?", "¿Solo ida o ida y vuelta?", "Einfach oder hin und zurück?"),
    N("Single. Soltera. ¿Le está preguntando si está casada? Sofía busca en la memoria las palabras de su aplicación americana y encuentra otras.",
      "Single. Ledig. Fragt er sie, ob sie verheiratet ist? Sofía sucht im Gedächtnis die Wörter aus ihrer amerikanischen App und findet andere."),
    Z("—Round trip, please.", "Ida y vuelta, por favor.", "Hin und zurück, bitte."),
    Z("—A return. Yes. “Round trip” is American. Here, a single is one way, and a return is there and back.", "Ida y vuelta, sí. «Round trip» es americano. Aquí «single» es solo ida, y «return» es ida y vuelta.", "Eine Rückfahrkarte. Ja. »Round trip« ist amerikanisch. Hier ist »single« die einfache Fahrt und »return« hin und zurück."),
    Z("—Thank you. A return, please. What time does it leave?", "Gracias. Ida y vuelta, por favor. ¿A qué hora sale?", "Danke. Hin und zurück, bitte. Wann fährt er ab?"),
    Z("—The next one leaves at nine twelve. It arrives at ten twenty-five.", "El próximo sale a las nueve y doce. Llega a las diez y veinticinco.", "Der nächste fährt um neun Uhr zwölf. Er kommt um zehn Uhr fünfundzwanzig an."),
    Z("—And which track?", "¿Y de qué vía?", "Und von welchem Gleis?"),
    Z("—Platform fifteen. That's thirty-one pounds forty, please.", "Andén quince. Son treinta y una libras con cuarenta, por favor.", "Bahnsteig fünfzehn. Das macht einunddreißig Pfund vierzig, bitte."),
    N("Track. Platform. Otra vez el inglés de Dan. Sofía empieza a llevar un cuaderno con dos columnas: a la izquierda, lo que dice Dan; a la derecha, lo que dice todo Londres. La columna de la izquierda crece deprisa.",
      "Track. Platform. Schon wieder Dans Englisch. Sofía fängt ein Heft mit zwei Spalten an: links, was Dan sagt; rechts, was ganz London sagt. Die linke Spalte wächst schnell."),
    Z("—Here's your ticket. Safe travels!", "Aquí tiene su billete. ¡Buen viaje!", "Hier ist Ihre Fahrkarte. Gute Reise!"),
    Z("On platform fifteen, the clock says nine eleven.", "En el andén quince, el reloj marca las nueve y once.", "Auf Bahnsteig fünfzehn zeigt die Uhr neun Uhr elf."),
    N("En su pueblo, los autobuses salen cuando el conductor termina el café.",
      "In ihrem Dorf fahren die Busse ab, wenn der Fahrer seinen Kaffee ausgetrunken hat."),
    Z("At nine twelve, the train leaves. Not at nine thirteen. At nine twelve.", "A las nueve y doce sale el tren. No a las nueve y trece. A las nueve y doce.", "Um neun Uhr zwölf fährt der Zug ab. Nicht um neun Uhr dreizehn. Um neun Uhr zwölf."),
    N("Un señor con traje se sienta enfrente, olfatea el aire, mira la mochila, se levanta y se cambia de asiento sin decir nada. Muy británico.",
      "Ein Herr im Anzug setzt sich gegenüber, schnuppert, schaut auf den Rucksack, steht auf und setzt sich woandershin, ohne ein Wort. Sehr britisch."),
    Z("—Sorry! It's the cheese!", "¡Perdón! ¡Es el queso!", "Entschuldigung! Das ist der Käse!"),
    Z("The train goes south. Houses, then gardens, then green hills and sheep.", "El tren va hacia el sur. Casas, luego jardines, luego colinas verdes y ovejas.", "Der Zug fährt nach Süden. Häuser, dann Gärten, dann grüne Hügel und Schafe."),
    N("Sofía no ha visto nunca un verde así. En Jalisco, en octubre, el campo también es verde, pero es un verde con prisa, que sabe que viene la seca. Este verde parece que no se va a ir nunca.",
      "So ein Grün hat Sofía noch nie gesehen. In Jalisco ist das Land im Oktober auch grün, aber es ist ein eiliges Grün, das weiß, dass die Trockenzeit kommt. Dieses Grün sieht aus, als würde es nie gehen."),
    Z("At ten twenty-five, the train arrives in Brighton. On time.", "A las diez y veinticinco, el tren llega a Brighton. Puntual.", "Um zehn Uhr fünfundzwanzig kommt der Zug in Brighton an. Pünktlich."),
    N("Sale de la estación y baja por una calle larga, con las gaviotas gritando encima. Al final de la calle, una línea gris plateada, inmensa, que se mueve.",
      "Sie verlässt den Bahnhof und geht eine lange Straße hinunter, über ihr kreischen die Möwen. Am Ende der Straße eine silbergraue Linie, riesig, die sich bewegt."),
    Z("The sea. Grey and silver. Cold and beautiful.", "El mar. Gris y plateado. Frío y precioso.", "Das Meer. Grau und silbern. Kalt und wunderschön."),
    N("En su pueblo no hay mar. Hasta los dieciocho años lo vio dos veces. Faltan dos horas y media. Se sienta en las piedras con la mochila y el queso, y lo mira como a un pariente lejano.",
      "In ihrem Dorf gibt es kein Meer. Bis achtzehn hat sie es zweimal gesehen. Noch zweieinhalb Stunden. Sie setzt sich mit Rucksack und Käse auf die Kiesel und schaut es an wie einen entfernten Verwandten."),
    Z("One o'clock. The captain.", "A la una. El capitán.", "Ein Uhr. Der Kapitän.")
  ]),

  // ── Station 6 · RESTAURANT ──────────────────────────────────────────
  S("fundament", 6, "restaurant", "I'll have the salmon",
    "Comida con el capitán Clarke frente al mar: un salmón, un examen, una pluma estilográfica y una gaviota sin modales.",
    "Mittagessen mit Kapitän Clarke am Meer: ein Lachs, eine Prüfung, ein Füller und eine Möwe ohne Manieren.",
  [
    N("A la una menos cinco, Sofía está delante del restaurante: una casa azul en el paseo marítimo, con redes de pesca en la ventana. A la una en punto llega un señor alto, con abrigo azul marino, gorra de capitán y bastón. No tiene prisa. Parece que el mundo lo espera a él.",
      "Um fünf vor eins steht Sofía vor dem Restaurant: ein blaues Haus an der Strandpromenade, mit Fischernetzen im Fenster. Um Punkt eins kommt ein großer Herr, in marineblauem Mantel, mit Kapitänsmütze und Stock. Er hat keine Eile. Es sieht aus, als warte die Welt auf ihn."),
    Z("—Miss Herrera? Desmond Clarke. You are on time. Good.", "¿La señorita Herrera? Desmond Clarke. Es usted puntual. Bien.", "Frau Herrera? Desmond Clarke. Sie sind pünktlich. Gut."),
    Z("A young waiter opens the door.", "Un camarero joven abre la puerta.", "Ein junger Kellner öffnet die Tür."),
    Z("—Good afternoon! How many in your party?", "¡Buenas tardes! ¿Cuántos son?", "Guten Tag! Wie viele Personen?"),
    Z("—Two, please. A table by the window.", "Dos, por favor. Una mesa junto a la ventana.", "Zwei, bitte. Einen Tisch am Fenster."),
    Z("—Right this way. Here are your menus.", "Por aquí, por favor. Aquí tienen la carta.", "Hier entlang, bitte. Hier sind die Speisekarten."),
    Z("Fish soup · Grilled salmon · Fish and chips · Crab salad · Apple crumble", "Sopa de pescado · Salmón a la parrilla · Pescado con patatas fritas · Ensalada de cangrejo · Crumble de manzana", "Fischsuppe · Gegrillter Lachs · Fish and Chips · Krebssalat · Apfel-Crumble"),
    N("El capitán no abre la carta. Se la sabe desde 1985. Mira a Sofía por encima de las gafas, y Sofía comprende que el examen ha empezado.",
      "Der Kapitän schlägt die Karte nicht auf. Er kennt sie seit 1985. Er sieht Sofía über die Brille hinweg an, und Sofía begreift, dass die Prüfung begonnen hat."),
    Z("—Ready to order?", "¿Ya saben qué van a pedir?", "Möchten Sie bestellen?"),
    Z("—What do you recommend?", "¿Qué me recomienda?", "Was empfehlen Sie?"),
    Z("—The grilled salmon is really good today.", "El salmón a la parrilla está muy bueno hoy.", "Der gegrillte Lachs ist heute sehr gut."),
    Z("—I'll have the salmon, then. With a side salad, please.", "Entonces, el salmón. Con ensalada de guarnición, por favor.", "Dann nehme ich den Lachs. Mit einem Beilagensalat, bitte."),
    Z("—Fish and chips for me. As always.", "Para mí, pescado con patatas fritas. Como siempre.", "Für mich Fish and Chips. Wie immer."),
    Z("—So, Miss Herrera. Why London?", "Bien, señorita Herrera. ¿Por qué Londres?", "Also, Frau Herrera. Warum London?"),
    Z("—I make books. I'm a book designer. London is full of books.", "Hago libros. Soy diseñadora de libros. Londres está lleno de libros.", "Ich mache Bücher. Ich bin Buchgestalterin. London ist voller Bücher."),
    Z("—And what book is on your desk now?", "¿Y qué libro tiene ahora en la mesa?", "Und welches Buch liegt gerade auf Ihrem Schreibtisch?"),
    Z("—A book about the sea. I design the cover.", "Un libro sobre el mar. Diseño la portada.", "Ein Buch über das Meer. Ich gestalte den Umschlag."),
    N("El capitán deja el tenedor. Saca de la cartera una foto vieja, doblada en cuatro: un barco gris sobre un mar de un azul imposible, casi violeta. Golfo de Guinea, 1981, dice. Pone un dedo grueso sobre el agua.",
      "Der Kapitän legt die Gabel hin. Er zieht ein altes, zweimal gefaltetes Foto aus der Brieftasche: ein graues Schiff auf einem Meer von unmöglichem Blau, fast violett. Golf von Guinea, 1981, sagt er. Er legt einen dicken Finger auf das Wasser."),
    Z("—Then make it blue. Not grey. Real blue. Like this.", "Entonces hágala azul. No gris. Azul de verdad. Como este.", "Dann machen Sie ihn blau. Nicht grau. Richtig blau. So wie das hier."),
    Z("—Yes, Captain.", "Sí, capitán.", "Jawohl, Kapitän."),
    Z("The food arrives. The salmon is perfect. The salad is fresh.", "Llega la comida. El salmón está perfecto. La ensalada, fresca.", "Das Essen kommt. Der Lachs ist perfekt. Der Salat ist frisch."),
    Z("—Is it good?", "¿Está bueno?", "Schmeckt es?"),
    Z("—It's delicious.", "Está buenísimo.", "Es ist köstlich."),
    Z("—Oh, and this is for you. From Mr Ade.", "Ah, y esto es para usted. De parte del señor Ade.", "Ach, und das ist für Sie. Von Mr Ade."),
    N("El capitán abre el paquete. El olor llena el restaurante en dos segundos. Una señora de la mesa de al lado deja el tenedor en el aire. El capitán cierra los ojos y sonríe por primera vez.",
      "Der Kapitän öffnet das Päckchen. In zwei Sekunden füllt der Geruch das Restaurant. Eine Dame am Nebentisch hält die Gabel in der Luft an. Der Kapitän schließt die Augen und lächelt zum ersten Mal."),
    Z("—Stilton. Good old Ade. He never forgets.", "Stilton. El bueno de Ade. Nunca se olvida.", "Stilton. Der gute alte Ade. Er vergisst nie etwas."),
    Z("—And this is the tenancy agreement. Can you sign it, please?", "Y este es el contrato de alquiler. ¿Puede firmarlo, por favor?", "Und das ist der Mietvertrag. Können Sie ihn bitte unterschreiben?"),
    N("Del bolsillo interior sale una pluma estilográfica negra, gastada, con un ancla dorada. El capitán lee el contrato entero, línea por línea, como quien lee un mapa antes de una tormenta. Luego firma despacio, en tinta azul. Azul de verdad.",
      "Aus der Innentasche kommt ein schwarzer, abgenutzter Füller mit einem goldenen Anker. Der Kapitän liest den ganzen Vertrag, Zeile für Zeile, wie man eine Karte vor einem Sturm liest. Dann unterschreibt er langsam, mit blauer Tinte. Richtig blau."),
    Z("—There. Signed. On paper. With a pen.", "Ya está. Firmado. En papel. Con pluma.", "So. Unterschrieben. Auf Papier. Mit einem Füller."),
    N("En ese momento, una gaviota enorme aterriza en la ventana abierta. Mira el plato del capitán con ojos de pirata. Un segundo después tiene una patata frita en el pico, y el capitán, una patata menos.",
      "In diesem Moment landet eine riesige Möwe im offenen Fenster. Sie betrachtet den Teller des Kapitäns mit Piratenaugen. Eine Sekunde später hat sie eine Pommes im Schnabel und der Kapitän eine Pommes weniger."),
    Z("—Thief! Pirate! Forty years at sea, and a seagull robs me!", "¡Ladrona! ¡Pirata! ¡Cuarenta años en el mar, y me roba una gaviota!", "Diebin! Piratin! Vierzig Jahre auf See, und eine Möwe beraubt mich!"),
    Z("Dessert is apple crumble. Then Sofía remembers Dan's word.", "De postre, crumble de manzana. Entonces Sofía se acuerda de la palabra de Dan.", "Zum Nachtisch gibt es Apfel-Crumble. Dann fällt Sofía Dans Wort ein."),
    Z("—The check, please.", "La cuenta, por favor.", "Die Rechnung, bitte."),
    Z("—A cheque? How did you know? I always pay by cheque.", "¿Un cheque? ¿Cómo lo sabe? Yo siempre pago con cheque.", "Ein Scheck? Woher wissen Sie das? Ich zahle immer mit Scheck."),
    N("«Check» y «cheque» suenan exactamente igual. Y el capitán saca un talonario. Un talonario de verdad, de papel, como en las películas antiguas. El camarero joven mira el cheque como si fuera un fósil. Sofía busca su cartera; el capitán levanta una mano. En su mesa, dice, paga el capitán.",
      "»Check« und »cheque« klingen genau gleich. Und der Kapitän zieht ein Scheckheft hervor. Ein echtes Scheckheft, aus Papier, wie in alten Filmen. Der junge Kellner betrachtet den Scheck, als wäre er ein Fossil. Sofía sucht ihr Portemonnaie; der Kapitän hebt die Hand. An seinem Tisch, sagt er, zahlt der Kapitän."),
    Z("—Thank you very much, Captain Clarke.", "Muchísimas gracias, capitán Clarke.", "Vielen Dank, Kapitän Clarke."),
    Z("—Take care of my flat. And say hello to Mrs Okafor. She knows everything.", "Cuide de mi piso. Y salude a la señora Okafor. Ella lo sabe todo.", "Passen Sie auf meine Wohnung auf. Und grüßen Sie Mrs Okafor. Sie weiß alles."),
    N("En el tren de vuelta, el contrato va en la carpeta, la carpeta en la mochila y la mochila sobre las rodillas. Ya no huele a queso. Huele a mar.",
      "Im Zug zurück steckt der Vertrag in der Mappe, die Mappe im Rucksack und der Rucksack liegt auf ihren Knien. Er riecht nicht mehr nach Käse. Er riecht nach Meer."),
    Z("Signed. Five days to Thursday.", "Firmado. Cinco días hasta el jueves.", "Unterschrieben. Noch fünf Tage bis Donnerstag.")
  ]),

  // ── Station 7 · WETTER ──────────────────────────────────────────────
  S("fundament", 7, "wetter", "It's supposed to rain",
    "Un domingo de sol, una vecina que lee el tiempo en sus palomas y una mexicana que no cree en la lluvia inglesa.",
    "Ein sonniger Sonntag, eine Nachbarin, die das Wetter an ihren Tauben abliest, und eine Mexikanerin, die nicht an englischen Regen glaubt.",
  [
    N("El domingo, Londres hace algo que nadie le había prometido: sale el sol. Diecinueve grados en octubre. La gente se tumba en los parques con los ojos cerrados, como lagartijas que no se lo creen.",
      "Am Sonntag tut London etwas, das ihr niemand versprochen hat: Die Sonne kommt heraus. Neunzehn Grad im Oktober. Die Leute liegen mit geschlossenen Augen in den Parks, wie Eidechsen, die es nicht glauben können."),
    Z("It is sunny and warm. The sky is blue. There are no clouds.", "Hace sol y calor. El cielo está azul. No hay nubes.", "Es ist sonnig und warm. Der Himmel ist blau. Es gibt keine Wolken."),
    N("Sofía vuelve de comprar pan. En la puerta de la planta baja hay una señora con un gorro de lana morado y una bolsa de semillas: la señora Okafor, la vecina que lo sabe todo. Vive aquí desde 1979. Delante de su ventana siempre hay palomas.",
      "Sofía kommt vom Brotkaufen zurück. An der Tür im Erdgeschoss steht eine Dame mit lila Wollmütze und einer Tüte Körner: Mrs Okafor, die Nachbarin, die alles weiß. Sie wohnt hier seit 1979. Vor ihrem Fenster sitzen immer Tauben."),
    Z("—Beautiful day, isn't it?", "Hace un día precioso, ¿verdad?", "Schöner Tag, nicht wahr?"),
    Z("—Yes, it's sunny and warm.", "Sí, hace sol y calor.", "Ja, es ist sonnig und warm."),
    Z("—Enjoy it. It's supposed to rain tomorrow.", "Disfrútalo. Mañana dicen que va a llover.", "Genieß es. Morgen soll es regnen."),
    Z("—Rain? But there are no clouds.", "¿Lluvia? Pero si no hay nubes.", "Regen? Aber es gibt keine Wolken."),
    Z("—Look at my pigeons. They are sitting low, on the wall. When they sit low, it rains.", "Mira mis palomas. Están posadas abajo, en el muro. Cuando se posan abajo, llueve.", "Schau dir meine Tauben an. Sie sitzen tief, auf der Mauer. Wenn sie tief sitzen, regnet es."),
    N("Sofía mira las palomas. Siete palomas grises sobre un muro bajo, con cara de no saber nada de nada.",
      "Sofía betrachtet die Tauben. Sieben graue Tauben auf einer niedrigen Mauer, mit Gesichtern, die von nichts eine Ahnung haben."),
    Z("—Do you have an umbrella, dear?", "¿Tienes paraguas, cariño?", "Hast du einen Regenschirm, Liebes?"),
    Z("—No. I'm from Jalisco. In summer, it rains every afternoon. Big rain. London rain is small.", "No. Soy de Jalisco. En verano llueve todas las tardes. Lluvia grande. La lluvia de Londres es pequeña.", "Nein. Ich komme aus Jalisco. Im Sommer regnet es jeden Nachmittag. Großer Regen. Londoner Regen ist klein."),
    N("Lo dice con orgullo. En su pueblo, en julio, el cielo se rompe a las cuatro y a las cinco ya está otra vez azul. Eso es lluvia. Lo de Londres, piensa, es humedad con mala educación.",
      "Sie sagt es mit Stolz. In ihrem Dorf bricht im Juli um vier der Himmel auf, und um fünf ist er schon wieder blau. Das ist Regen. Das in London, denkt sie, ist Feuchtigkeit mit schlechten Manieren."),
    Z("—Small? Ha! The pigeons are never wrong.", "¿Pequeña? ¡Ja! Las palomas nunca se equivocan.", "Klein? Ha! Die Tauben irren sich nie."),
    Z("Upstairs, Priya looks at her phone.", "Arriba, Priya mira el móvil.", "Oben schaut Priya auf ihr Handy."),
    Z("—Ninety per cent rain tomorrow. Take my umbrella.", "Mañana, noventa por ciento de lluvia. Llévate mi paraguas.", "Morgen neunzig Prozent Regen. Nimm meinen Schirm."),
    Z("—No, thanks. I don't need an umbrella.", "No, gracias. No necesito paraguas.", "Nein, danke. Ich brauche keinen Schirm."),
    N("Priya no insiste. Deja el paraguas junto a la puerta. Por si acaso.",
      "Priya besteht nicht darauf. Sie stellt den Schirm neben die Tür. Für alle Fälle."),
    Z("The next morning, the pigeons are not on the wall. They are under the roof.", "A la mañana siguiente, las palomas no están en el muro. Están debajo del tejado.", "Am nächsten Morgen sind die Tauben nicht auf der Mauer. Sie sitzen unter dem Dach."),
    Z("Sofía walks to the station. Priya's umbrella is still by the door.", "Sofía va andando a la estación. El paraguas de Priya sigue junto a la puerta.", "Sofía geht zu Fuß zum Bahnhof. Priyas Schirm steht immer noch neben der Tür."),
    N("A las once empieza. No es la lluvia de Jalisco, que cae de arriba abajo, honrada, y se va. Esta viene de lado, de abajo, de todas partes, con viento. Y no se va.",
      "Um elf fängt es an. Es ist nicht der Regen von Jalisco, der ehrlich von oben nach unten fällt und wieder geht. Dieser kommt von der Seite, von unten, von überall, mit Wind. Und er geht nicht."),
    Z("It rains. It rains all day. And it is very windy.", "Llueve. Llueve todo el día. Y hace mucho viento.", "Es regnet. Es regnet den ganzen Tag. Und es ist sehr windig."),
    Z("In the street, a man's umbrella turns inside out. He says “Sorry” — to the umbrella.", "En la calle, el paraguas de un hombre se da la vuelta. Él dice «perdón»… al paraguas.", "Auf der Straße stülpt sich der Schirm eines Mannes um. Er sagt »Entschuldigung« — zum Schirm."),
    N("Por la tarde, Sofía vuelve a casa sin un centímetro seco. Los zapatos hacen ruido de rana.",
      "Am Abend kommt Sofía ohne einen trockenen Zentimeter nach Hause. Ihre Schuhe machen Froschgeräusche."),
    Z("Mrs Okafor is at her window. She says nothing. She only points at the pigeons.", "La señora Okafor está en su ventana. No dice nada. Solo señala las palomas.", "Mrs Okafor steht an ihrem Fenster. Sie sagt nichts. Sie zeigt nur auf die Tauben."),
    Z("Upstairs, Priya gives her a towel and a cup of tea. With milk.", "Arriba, Priya le da una toalla y una taza de té. Con leche.", "Oben gibt Priya ihr ein Handtuch und eine Tasse Tee. Mit Milch."),
    Z("—Drink. Don't argue.", "Bebe. Y no discutas.", "Trink. Keine Widerrede."),
    N("Sofía bebe porque tiene frío. Luego bebe porque está caliente. Luego bebe porque —y esto no se lo contará nunca a su madre— está buenísimo. Suave, dulce, como el abrazo de alguien que habla poco.",
      "Sofía trinkt, weil ihr kalt ist. Dann trinkt sie, weil er heiß ist. Dann trinkt sie, weil er — und das wird sie ihrer Mutter nie erzählen — wunderbar schmeckt. Weich, süß, wie die Umarmung von jemandem, der wenig redet."),
    Z("—Well?", "¿Y bien?", "Na?"),
    Z("—It's… good. Can I have another cup, please?", "Está… bueno. ¿Me pones otra taza, por favor?", "Er ist … gut. Kann ich bitte noch eine Tasse haben?"),
    N("Priya sonríe como quien gana una apuesta. Por la noche, a Sofía le arde la garganta. Abajo, siete palomas duermen bajo el tejado, secas.",
      "Priya lächelt wie jemand, der eine Wette gewonnen hat. In der Nacht brennt Sofías Hals. Unten schlafen sieben Tauben unter dem Dach, trocken."),
    Z("The pigeons are never wrong.", "Las palomas nunca se equivocan.", "Die Tauben irren sich nie.")
  ]),

  // ── Station 8 · ARZT ────────────────────────────────────────────────
  S("fundament", 8, "arzt", "I have a headache",
    "Fiebre, una recepcionista con gafas rojas y otra vez la misma pregunta: ¿tiene usted un justificante de domicilio?",
    "Fieber, eine Empfangsdame mit roter Brille und schon wieder dieselbe Frage: Haben Sie einen Wohnsitznachweis?",
  [
    N("Martes. Sofía se despierta con la cabeza como un tambor y la garganta llena de cristales. Treinta y ocho y medio. Priya le pone la mano en la frente y dice una sola palabra: «Médico».",
      "Dienstag. Sofía wacht mit einem Kopf wie eine Trommel und einem Hals voller Glasscherben auf. Achtunddreißigeinhalb. Priya legt ihr die Hand auf die Stirn und sagt nur ein Wort: »Arzt.«"),
    N("En Inglaterra, explica, primero se va al médico de cabecera, el GP. Pero hay que estar registrado. El centro de salud está a dos calles. Dos calles, no dos manzanas.",
      "In England, erklärt sie, geht man zuerst zum Hausarzt, dem GP. Aber man muss dort registriert sein. Die Praxis ist zwei Straßen weiter. Zwei Straßen, nicht zwei Blocks."),
    Z("At the GP surgery, there is a receptionist with red glasses.", "En el centro de salud hay una recepcionista con gafas rojas.", "In der Hausarztpraxis sitzt eine Empfangsdame mit roter Brille."),
    Z("—Good morning. Are you registered with us?", "Buenos días. ¿Está usted registrada aquí?", "Guten Morgen. Sind Sie bei uns registriert?"),
    Z("—No. I want to register, please.", "No. Quiero registrarme, por favor.", "Nein. Ich möchte mich bitte registrieren."),
    Z("—No problem. I need your passport and proof of address.", "Sin problema. Necesito su pasaporte y un justificante de domicilio.", "Kein Problem. Ich brauche Ihren Pass und einen Wohnsitznachweis."),
    N("Sofía se ríe. No porque sea gracioso. Se ríe como se ríe alguien con fiebre a quien le piden, otra vez, esas tres palabras. El contrato firmado está en casa, en la carpeta. Pero el registro tarda unos días, y la fiebre es hoy.",
      "Sofía lacht. Nicht, weil es lustig ist. Sie lacht, wie jemand mit Fieber lacht, den man schon wieder nach diesen drei Wörtern fragt. Der unterschriebene Vertrag liegt zu Hause, in der Mappe. Aber die Registrierung dauert ein paar Tage, und das Fieber ist heute."),
    Z("—For today, go to the walk-in centre. It's next to the station. No appointment.", "Para hoy, vaya al walk-in centre, el centro sin cita previa. Está al lado de la estación. No hace falta cita.", "Für heute gehen Sie ins Walk-in-Zentrum. Es ist neben dem Bahnhof. Ohne Termin."),
    Z("She waits one hour. Then a young doctor calls her name: “Sofia Herrera?” Without the accent.", "Espera una hora. Luego una doctora joven dice su nombre: «¿Sofia Herrera?». Sin tilde.", "Sie wartet eine Stunde. Dann ruft eine junge Ärztin ihren Namen: »Sofia Herrera?« Ohne Akzent."),
    N("Sin tilde. A una diseñadora le duelen esas cosas. Hoy le duele todo lo demás.",
      "Ohne Akzent. Einer Buchgestalterin tut so etwas weh. Heute tut ihr alles andere weh."),
    Z("—Hello. What brings you in today?", "Hola. ¿Qué la trae por aquí?", "Hallo. Was führt Sie heute zu uns?"),
    Z("—I have a headache.", "Me duele la cabeza.", "Ich habe Kopfschmerzen."),
    Z("—How long has that been going on?", "¿Desde cuándo?", "Seit wann haben Sie das?"),
    Z("—Since yesterday. And I have a fever.", "Desde ayer. Y tengo fiebre.", "Seit gestern. Und ich habe Fieber."),
    Z("—Do you cough? Are you tired?", "¿Tiene tos? ¿Está cansada?", "Husten Sie? Sind Sie müde?"),
    Z("—Yes. I'm very tired.", "Sí. Estoy muy cansada.", "Ja. Ich bin sehr müde."),
    N("La doctora le mira la garganta, le escucha los pulmones y le pregunta si ayer estuvo bajo la lluvia. Sofía piensa en siete palomas y dice que sí.",
      "Die Ärztin schaut ihr in den Hals, hört die Lunge ab und fragt, ob sie gestern im Regen war. Sofía denkt an sieben Tauben und sagt ja."),
    Z("—It's a cold, with a little fever. Take one of these and rest for a couple of days.", "Es un resfriado, con un poco de fiebre. Tómese una de estas y descanse un par de días.", "Das ist eine Erkältung mit etwas Fieber. Nehmen Sie eine davon und ruhen Sie sich ein paar Tage aus."),
    Z("—A couple of days? But on Thursday I have an appointment. At the bank. At nine thirty.", "¿Un par de días? Pero el jueves tengo una cita. En el banco. A las nueve y media.", "Ein paar Tage? Aber am Donnerstag habe ich einen Termin. Bei der Bank. Um halb zehn."),
    Z("—Then rest today and tomorrow. On Thursday, the bank. And after the bank, bed.", "Entonces descanse hoy y mañana. El jueves, el banco. Y después del banco, a la cama.", "Dann ruhen Sie sich heute und morgen aus. Am Donnerstag die Bank. Und nach der Bank ins Bett."),
    Z("—Do I need insurance?", "¿Necesito seguro?", "Brauche ich eine Versicherung?"),
    Z("—No. This is the NHS. Here's your prescription. The pharmacy is next door.", "No. Esto es la sanidad pública. Aquí tiene la receta. La farmacia está al lado.", "Nein. Das ist der NHS, der staatliche Gesundheitsdienst. Hier ist Ihr Rezept. Die Apotheke ist nebenan."),
    N("NHS: el servicio público de salud. La consulta no se paga: sin seguro, sin preguntas. Sofía no lo entiende del todo, pero le dan ganas de abrazar a alguien. Con fiebre, mejor no.",
      "NHS: der staatliche Gesundheitsdienst. Die Behandlung kostet nichts: keine Versicherung, keine Fragen. Sofía versteht es nicht ganz, aber sie möchte jemanden umarmen. Mit Fieber lieber nicht."),
    Z("—Feel better soon!", "¡Que se mejore!", "Gute Besserung!"),
    Z("Mrs Okafor calls the pharmacy “the chemist”. Dan calls it “the drugstore”. Sofía calls it “the place with the pills”.", "La señora Okafor llama a la farmacia «the chemist». Dan la llama «the drugstore». Sofía la llama «el sitio de las pastillas».", "Mrs Okafor nennt die Apotheke »the chemist«. Dan nennt sie »the drugstore«. Sofía nennt sie »der Ort mit den Tabletten«."),
    N("En casa, Priya ha dejado en la mesa una tetera, un limón y una nota en letra de programadora: «Té con leche O té con limón. Tú eliges. No hables». Sofía se mete en la cama con la carpeta de plástico en la mesilla, donde pueda verla.",
      "Zu Hause hat Priya eine Teekanne, eine Zitrone und einen Zettel in Programmiererinnen-Schrift auf den Tisch gelegt: »Tee mit Milch ODER Tee mit Zitrone. Du entscheidest. Nicht reden.« Sofía geht ins Bett, die Plastikmappe auf dem Nachttisch, wo sie sie sehen kann."),
    Z("Rest today. Rest tomorrow. On Thursday, the bank.", "Hoy, descansar. Mañana, descansar. El jueves, el banco.", "Heute ausruhen. Morgen ausruhen. Am Donnerstag die Bank.")
  ]),

  // ── Station 9 · HOTEL ───────────────────────────────────────────────
  S("fundament", 9, "hotel", "Under the name Herrera",
    "Olor a gas a medianoche, una calle llena de vecinos en pijama y un hotel donde nadie sabe escribir «Herrera».",
    "Gasgeruch um Mitternacht, eine Straße voller Nachbarn im Schlafanzug und ein Hotel, in dem niemand »Herrera« schreiben kann.",
  [
    N("Martes por la noche, las once y media. Sofía duerme con fiebre y sueña con palomas que firman contratos. Entonces alguien golpea la puerta. Fuerte.",
      "Dienstagnacht, halb zwölf. Sofía schläft mit Fieber und träumt von Tauben, die Verträge unterschreiben. Dann hämmert jemand an die Tür. Laut."),
    Z("—Gas! There's a smell of gas! Everybody out!", "¡Gas! ¡Huele a gas! ¡Todo el mundo fuera!", "Gas! Es riecht nach Gas! Alle raus!"),
    Z("It is Mrs Okafor, in her dressing gown and her purple hat.", "Es la señora Okafor, en bata y con su gorro morado.", "Es ist Mrs Okafor, im Morgenmantel und mit ihrer lila Mütze."),
    N("Sí, huele: un olor dulce y feo que sube de la vieja caldera del sótano.",
      "Ja, es riecht: ein süßlicher, hässlicher Geruch, der aus dem alten Heizkessel im Keller aufsteigt."),
    Z("Sofía cannot find her shoes. She cannot find her coat. But she finds the plastic folder.", "Sofía no encuentra los zapatos. No encuentra el abrigo. Pero encuentra la carpeta de plástico.", "Sofía findet ihre Schuhe nicht. Sie findet ihren Mantel nicht. Aber sie findet die Plastikmappe."),
    N("La agarra antes que nada.",
      "Die packt sie vor allem anderen."),
    Z("Five minutes later, Sofía is in the street in her pyjamas, with slippers and a plastic folder.", "Cinco minutos después, Sofía está en la calle en pijama, con zapatillas y una carpeta de plástico.", "Fünf Minuten später steht Sofía im Schlafanzug auf der Straße, mit Hausschuhen und einer Plastikmappe."),
    Z("—What's in the folder?", "¿Qué hay en la carpeta?", "Was ist in der Mappe?"),
    Z("—My tenancy agreement. Signed.", "Mi contrato de alquiler. Firmado.", "Mein Mietvertrag. Unterschrieben."),
    Z("—Not your phone? Not your passport?", "¿Y el móvil? ¿Y el pasaporte?", "Nicht dein Handy? Nicht dein Pass?"),
    Z("—The passport is in the folder too. The phone is upstairs.", "El pasaporte también está en la carpeta. El móvil está arriba.", "Der Pass ist auch in der Mappe. Das Handy ist oben."),
    Z("The firefighters come. They turn off the gas. The old boiler is dead.", "Llegan los bomberos. Cierran el gas. La vieja caldera está muerta.", "Die Feuerwehr kommt. Sie drehen das Gas ab. Der alte Heizkessel ist tot."),
    N("Hasta el jueves, en el edificio no duerme nadie. Priya ya está buscando en su móvil.",
      "Bis Donnerstag schläft niemand im Haus. Priya sucht schon auf ihrem Handy."),
    Z("Priya finds a small hotel near the station. Two nights, three rooms.", "Priya encuentra un hotel pequeño cerca de la estación. Dos noches, tres habitaciones.", "Priya findet ein kleines Hotel in der Nähe des Bahnhofs. Zwei Nächte, drei Zimmer."),
    Z("The hotel is called The Albany. The carpet has flowers on it.", "El hotel se llama The Albany. La moqueta tiene flores.", "Das Hotel heißt The Albany. Der Teppichboden hat Blumen."),
    N("Flores de los años setenta. En la recepción, un chico con cara de sueño.",
      "Blumen aus den Siebzigern. An der Rezeption ein junger Mann mit verschlafenem Gesicht."),
    Z("—Good evening. Checking in?", "Buenas noches. ¿Viene a registrarse?", "Guten Abend. Möchten Sie einchecken?"),
    Z("—Yes, under the name Herrera.", "Sí, a nombre de Herrera.", "Ja, auf den Namen Herrera."),
    N("Lo dice como en Jalisco: sin hache, con una erre que vibra. «Errrera». El recepcionista teclea, busca y frunce el ceño.",
      "Sie sagt es wie in Jalisco: ohne H, mit einem rollenden R. »Errrera«. Der Rezeptionist tippt, sucht und runzelt die Stirn."),
    Z("—Sorry… I have no “Errera”.", "Lo siento… No tengo ninguna «Errera».", "Tut mir leid … Ich habe keine »Errera«."),
    Z("—Sorry! With an H. H-E-R-R-E-R-A.", "¡Perdón! Con hache. H-E-R-R-E-R-A.", "Entschuldigung! Mit H. H-E-R-R-E-R-A."),
    N("Pero dice la hache en español, «hache», y el chico escribe una A. Priya interviene con voz de programadora que corrige un error:",
      "Aber sie spricht das H spanisch aus, »atsche«, und der junge Mann schreibt ein A. Priya greift ein, mit der Stimme einer Programmiererin, die einen Fehler behebt:"),
    Z("—“Aitch”. H, like “hotel”.", "«Aitch». H, como en «hotel».", "»Aitch«. H wie »Hotel«."),
    Z("—Ah! Herrera. Got it. Two nights, right? Can I see your ID, please?", "¡Ah! Herrera. Ya lo tengo. Dos noches, ¿verdad? ¿Me enseña su documento de identidad, por favor?", "Ah! Herrera. Hab’s. Zwei Nächte, richtig? Kann ich bitte Ihren Ausweis sehen?"),
    N("Sofía abre la carpeta y saca el pasaporte. El chico mira el pijama, las zapatillas, la carpeta, y decide no preguntar nada. Es un profesional.",
      "Sofía öffnet die Mappe und nimmt den Pass heraus. Der junge Mann betrachtet den Schlafanzug, die Hausschuhe, die Mappe und beschließt, nichts zu fragen. Er ist ein Profi."),
    Z("—Thank you. Here's your key. Room three one two.", "Gracias. Aquí tiene su llave. Habitación trescientos doce.", "Danke. Hier ist Ihr Schlüssel. Zimmer drei eins zwei."),
    Z("—Thanks. Is breakfast included?", "Gracias. ¿El desayuno está incluido?", "Danke. Ist das Frühstück inbegriffen?"),
    Z("—It is. Seven to ten, in the dining room.", "Sí. De siete a diez, en el comedor.", "Ja. Von sieben bis zehn, im Speisesaal."),
    Z("—Great. What floor is the room on?", "Estupendo. ¿En qué planta está la habitación?", "Prima. In welchem Stock ist das Zimmer?"),
    Z("—The third floor. The lift is around the corner.", "En la tercera planta. El ascensor está a la vuelta de la esquina.", "Im dritten Stock. Der Aufzug ist um die Ecke."),
    Z("—An elevator! Finally! Our building has no elevator.", "¡Un ascensor! ¡Por fin! Nuestro edificio no tiene ascensor.", "Ein Aufzug! Endlich! Unser Haus hat keinen Aufzug."),
    Z("—A lift, Dan. In London, it's a lift.", "Un «lift», Dan. En Londres se dice «lift».", "Ein »lift«, Dan. In London heißt das »lift«."),
    N("Dan la mira con la boca abierta. Priya aplaude despacio. Dos semanas en Londres, y Sofía corrige a un americano. El recepcionista, sin levantar la vista, dice una sola palabra:",
      "Dan starrt sie mit offenem Mund an. Priya klatscht langsam. Zwei Wochen in London, und Sofía korrigiert einen Amerikaner. Der Rezeptionist sagt, ohne aufzusehen, ein einziges Wort:"),
    Z("—Correct.", "Correcto.", "Richtig."),
    N("En la habitación 312 hay una cama blanda, un radiador que suena como un tren lejano y una ventana a la calle. Sofía pone la carpeta debajo de la almohada, como una niña que guarda un diente para el ratoncito Pérez.",
      "In Zimmer 312 gibt es ein weiches Bett, einen Heizkörper, der wie ein ferner Zug klingt, und ein Fenster zur Straße. Sofía legt die Mappe unter das Kopfkissen, wie ein Kind, das einen Milchzahn für die Zahnfee aufbewahrt."),
    Z("Thursday, nine thirty. One more day.", "Jueves, nueve y media. Un día más.", "Donnerstag, halb zehn. Noch ein Tag.")
  ]),

  // ── Station 10 · FAMILIE ────────────────────────────────────────────
  S("fundament", 10, "familie", "His name is Mateo",
    "La cita en el banco, un ordenador lento, un empleado con un hijo de doce años y, por la noche, una videollamada a Jalisco.",
    "Der Banktermin, ein langsamer Computer, ein Bankangestellter mit einem zwölfjährigen Sohn und am Abend ein Videoanruf nach Jalisco.",
  [
    N("Jueves, 24 de octubre. Treinta y siete con dos. La doctora tenía razón: descansar funciona, incluso en un hotel con moqueta de flores.",
      "Donnerstag, 24. Oktober. Siebenunddreißig Komma zwei. Die Ärztin hatte recht: Ausruhen hilft, sogar in einem Hotel mit geblümtem Teppich."),
    Z("At breakfast, Sofía orders like a Londoner.", "En el desayuno, Sofía pide como una londinense.", "Beim Frühstück bestellt Sofía wie eine Londonerin."),
    Z("—Tea with milk, please. And toast.", "Té con leche, por favor. Y una tostada.", "Tee mit Milch, bitte. Und Toast."),
    N("Priya casi se atraganta. Dan pide café doble, por todos los americanos del mundo.",
      "Priya verschluckt sich fast. Dan bestellt einen doppelten Kaffee, für alle Amerikaner der Welt."),
    Z("At nine twenty-five, Sofía is at the bank in Trafalgar Square. She has her passport and the signed tenancy agreement. The lions are still there. So are the pigeons.", "A las nueve y veinticinco, Sofía está en el banco de Trafalgar Square. Lleva el pasaporte y el contrato de alquiler firmado. Los leones siguen ahí. Las palomas, también.", "Um neun Uhr fünfundzwanzig ist Sofía in der Bank am Trafalgar Square. Sie hat ihren Pass und den unterschriebenen Mietvertrag dabei. Die Löwen sind noch da. Die Tauben auch."),
    Z("A man in a grey suit calls her name. He says “Sofía” correctly, with the accent on the í.", "Un hombre de traje gris dice su nombre. Dice «Sofía» bien, con el acento en la í.", "Ein Mann im grauen Anzug ruft ihren Namen. Er sagt »Sofía« richtig, mit der Betonung auf dem í."),
    Z("—Good morning. I'm Gareth Evans. Please sit down.", "Buenos días. Soy Gareth Evans. Siéntese, por favor.", "Guten Morgen. Ich bin Gareth Evans. Bitte setzen Sie sich."),
    Z("—Good morning. I have an appointment at nine thirty. Here is my passport. And here is my proof of address.", "Buenos días. Tengo una cita a las nueve y media. Aquí está mi pasaporte. Y aquí está mi justificante de domicilio.", "Guten Morgen. Ich habe einen Termin um halb zehn. Hier ist mein Pass. Und hier ist mein Wohnsitznachweis."),
    N("Lo dice de un tirón, sin respirar. Ha tardado dieciséis días en poder decir esa frase. El señor Evans lee el contrato, ve la firma azul del capitán y levanta las cejas.",
      "Sie sagt es in einem Atemzug. Sechzehn Tage hat es gedauert, bis sie diesen Satz sagen konnte. Mr Evans liest den Vertrag, sieht die blaue Unterschrift des Kapitäns und hebt die Augenbrauen."),
    Z("—Signed by the landlord. With a fountain pen! Very nice.", "Firmado por el casero. ¡Con pluma estilográfica! Muy bonito.", "Vom Vermieter unterschrieben. Mit Füller! Sehr schön."),
    Z("Then he types. And types. The computer is slow. Very slow.", "Luego teclea. Y teclea. El ordenador es lento. Muy lento.", "Dann tippt er. Und tippt. Der Computer ist langsam. Sehr langsam."),
    Z("—Sorry. The computer thinks a lot today. So tell me — do you have any brothers or sisters?", "Perdone. El ordenador piensa mucho hoy. Cuénteme, ¿tiene hermanos?", "Entschuldigung. Der Computer denkt heute viel nach. Erzählen Sie mal — haben Sie Geschwister?"),
    Z("—Yes, I have a brother.", "Sí, tengo un hermano.", "Ja, ich habe einen Bruder."),
    Z("—Nice! What's his name?", "¡Qué bien! ¿Cómo se llama?", "Schön! Wie heißt er?"),
    Z("—His name is Mateo.", "Se llama Mateo.", "Er heißt Mateo."),
    Z("—That's a nice name. How old is he?", "Es un nombre bonito. ¿Cuántos años tiene?", "Das ist ein schöner Name. Wie alt ist er?"),
    Z("—He's twelve.", "Tiene doce años.", "Er ist zwölf."),
    Z("—Twelve! My son is twelve too. He plays football, and he never does his homework.", "¡Doce! Mi hijo también tiene doce. Juega al fútbol y nunca hace los deberes.", "Zwölf! Mein Sohn ist auch zwölf. Er spielt Fußball und macht nie seine Hausaufgaben."),
    Z("—Mateo plays football too. And he never does his homework.", "Mateo también juega al fútbol. Y nunca hace los deberes.", "Mateo spielt auch Fußball. Und er macht nie seine Hausaufgaben."),
    N("Se ríen los dos. Un padre galés y una hermana mayor mexicana, unidos por todos los deberes que nadie hace en el mundo.",
      "Beide lachen. Ein walisischer Vater und eine mexikanische große Schwester, vereint durch alle Hausaufgaben der Welt, die niemand macht."),
    Z("—And your parents?", "¿Y sus padres?", "Und Ihre Eltern?"),
    Z("—My mum and dad have a bakery. A small bakery in my town.", "Mis padres tienen una panadería. Una panadería pequeña en mi pueblo.", "Meine Mama und mein Papa haben eine Bäckerei. Eine kleine Bäckerei in meinem Dorf."),
    N("Mum. Lo dice sin pensar. Ni «mom» ni «mamá»: «mum». Dieciséis días en Londres.",
      "Mum. Sie sagt es, ohne nachzudenken. Weder »mom« noch »Mama«: »mum«. Sechzehn Tage in London."),
    Z("Then the computer says “ping”.", "Entonces el ordenador hace «ping».", "Dann macht der Computer »ping«."),
    Z("—There. Your account is open. Your bank card comes by post in five days. To your address.", "Listo. Su cuenta está abierta. La tarjeta le llega por correo en cinco días. A su dirección.", "So. Ihr Konto ist eröffnet. Ihre Bankkarte kommt in fünf Tagen mit der Post. An Ihre Adresse."),
    N("A su dirección. Una carta del banco, con su nombre y su dirección. Es decir: su próximo justificante de domicilio. El círculo, por fin, la deja entrar.",
      "An ihre Adresse. Ein Brief der Bank, mit ihrem Namen und ihrer Adresse. Also: ihr nächster Wohnsitznachweis. Der Kreis lässt sie endlich hinein."),
    Z("—Welcome to London, Ms Herrera.", "Bienvenida a Londres, señora Herrera.", "Willkommen in London, Frau Herrera."),
    N("En la plaza, Sofía manda los datos a Recursos Humanos. Enviado. Un día antes del plazo. Una paloma la mira. Esta vez, Sofía no le pide perdón.",
      "Auf dem Platz schickt Sofía die Daten an die Personalabteilung. Gesendet. Einen Tag vor der Frist. Eine Taube sieht sie an. Diesmal entschuldigt sich Sofía nicht."),
    Z("In the evening, the flat is warm again. The boiler is new. Sofía calls her family on video.", "Por la noche, el piso vuelve a estar caliente. La caldera es nueva. Sofía llama a su familia por videollamada.", "Am Abend ist die Wohnung wieder warm. Der Heizkessel ist neu. Sofía ruft ihre Familie per Video an."),
    Z("Three faces are on the screen: her mum, Lupe, her dad, Ernesto, and Mateo. Behind them is the bakery.", "Hay tres caras en la pantalla: su madre, Lupe; su padre, Ernesto; y Mateo. Detrás está la panadería.", "Drei Gesichter sind auf dem Bildschirm: ihre Mutter Lupe, ihr Vater Ernesto und Mateo. Dahinter ist die Bäckerei."),
    N("Su padre acerca a la cámara una concha recién hecha, como si se pudiera oler. Mateo aprende inglés con vídeos americanos.",
      "Ihr Vater hält eine frisch gebackene Concha vor die Kamera, als könnte man sie riechen. Mateo lernt Englisch mit amerikanischen Videos."),
    Z("—Hi, sis! Mom says you are too thin!", "¡Hola, hermanita! ¡Mamá dice que estás muy flaca!", "Hi, Schwesterherz! Mama sagt, du bist zu dünn!"),
    Z("—In London, we say “mum”, Mateo. Not “mom”.", "En Londres decimos «mum», Mateo. No «mom».", "In London sagen wir »mum«, Mateo. Nicht »mom«."),
    Z("—Mum? Like a mummy?", "¿«Mum»? ¿Como una momia?", "»Mum«? Wie eine Mumie?"),
    N("Su madre no entiende nada, pero se ríe porque Mateo se ríe. Luego le quita el móvil y se pone seria. «Ya tenemos los vuelos. Llegamos el trece de diciembre. Los tres. Para Navidad».",
      "Ihre Mutter versteht nichts, aber sie lacht, weil Mateo lacht. Dann nimmt sie ihm das Handy weg und wird ernst. »Wir haben die Flüge. Wir kommen am dreizehnten Dezember. Alle drei. Zu Weihnachten.«"),
    Z("—All three? Mum, Dad and Mateo? Here, in London? For Christmas?", "¿Los tres? ¿Mamá, papá y Mateo? ¿Aquí, en Londres? ¿Para Navidad?", "Alle drei? Mama, Papa und Mateo? Hier, in London? Zu Weihnachten?"),
    N("Su padre promete pan dulce para todo Londres. Cuando cuelgan, Sofía abre su cuaderno de dos columnas y, debajo, escribe tres frases en una sola columna.",
      "Ihr Vater verspricht süßes Brot für ganz London. Als sie aufgelegt haben, öffnet Sofía ihr Heft mit den zwei Spalten und schreibt darunter drei Sätze in eine einzige Spalte."),
    Z("I have an address. I have a bank account. And at Christmas, I have my family.", "Tengo una dirección. Tengo una cuenta en el banco. Y en Navidad, tengo a mi familia.", "Ich habe eine Adresse. Ich habe ein Bankkonto. Und an Weihnachten habe ich meine Familie.")
  ])
  ];
})(window);

/* ──────────────────────────────────────────────────────────────────────────
   lr-parts/sofia-2.js — „Sofía in London" · Zielsprache Englisch
   TEIL II · AUFBAU · „The visit" (Stationen 11–20, A2) + EPILOG (21, Anwendung)
   Muttersprachen: es (castellano de España), de (Hochdeutsch).
   N(es, de) = Erzählung Muttersprache · Z(en, es, de) = Englisch + Brücken ·
   P(en) = englische Prosa (nur Epilog, ein Sprecher pro Absatz).
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_SOFIA = w.__LR_PARTS_SOFIA || {};
  function N(a, b) { return { na: { es: a, de: b } }; }
  function Z(z, a, b) { var o = { z: z }; if (a) o.tr = { es: a, de: b }; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, teaserA, teaserB, body) {
    return { level: level, n: n, thema: thema, title: title, teaser: { es: teaserA, de: teaserB }, body: body };
  }

  K.teil2 = [

  // ── Station 11 · TAXI (A2) ──────────────────────────────────────────
  S('aufbau', 11, 'taxi', "I'm in a bit of a rush",
    "Siete semanas después. La familia aterriza en Heathrow a las cuatro y media, y media Inglaterra está en la autopista. Por suerte, conduce Del.",
    "Sieben Wochen später. Die Familie landet um halb fünf in Heathrow, und halb England steht auf der Autobahn. Zum Glück fährt Del.",
  [
    Z("Seven weeks went by. It was December now.", "Pasaron siete semanas. Ya era diciembre.", "Sieben Wochen vergingen. Jetzt war Dezember."),
    Z("Sofía had a bank account, a salary and a favourite table at Mrs Georgiou's café. She did not get lost in Kentish Town any more.", "Sofía tenía una cuenta en el banco, un sueldo y una mesa favorita en el café de la señora Georgiou. Ya no se perdía en Kentish Town.", "Sofía hatte ein Bankkonto, ein Gehalt und einen Lieblingstisch im Café von Mrs Georgiou. In Kentish Town verlief sie sich nicht mehr."),
    N("Y decía «sorry» unas cuarenta veces al día. A la gente, a las puertas, una vez incluso a una paloma de la señora Okafor. Priya lo llamaba «el síntoma».",
      "Und sie sagte etwa vierzigmal am Tag »sorry«. Zu Menschen, zu Türen, einmal sogar zu einer Taube von Mrs Okafor. Priya nannte es »das Symptom«."),
    Z("On Friday the thirteenth of December, her family was landing at Heathrow at half past four.", "El viernes trece de diciembre, su familia aterrizaba en Heathrow a las cuatro y media.", "Am Freitag, dem dreizehnten Dezember, landete ihre Familie um halb fünf in Heathrow."),
    N("Pero eran las tres y media y Sofía seguía en la editorial, con la portada de un libro de recetas que, según su jefa, parecía «un poco triste».",
      "Aber es war halb vier, und Sofía saß noch im Verlag, über dem Cover eines Kochbuchs, das laut ihrer Chefin »ein bisschen traurig« aussah."),
    Z("Sofía ran out into the street and raised her hand. A black cab stopped.", "Sofía salió corriendo a la calle y levantó la mano. Paró un taxi negro.", "Sofía rannte auf die Straße und hob die Hand. Ein schwarzes Taxi hielt."),
    Z("—Heathrow, please! Terminal two. I'm in a bit of a rush.", "¡A Heathrow, por favor! Terminal dos. Tengo un poco de prisa.", "Nach Heathrow, bitte! Terminal zwei. Ich habe es ein bisschen eilig."),
    N("El taxista se dio la vuelta. Gorra de lana. Gafas en la punta de la nariz. Una radio que hablaba de fútbol.",
      "Der Fahrer drehte sich um. Wollmütze. Brille auf der Nasenspitze. Ein Radio, das über Fußball redete."),
    Z("—Well, well. Miss Proof of Address! Hop in, love.", "¡Vaya, vaya! ¡La señorita del justificante de domicilio! Sube, cielo.", "Na so was! Fräulein Wohnsitznachweis! Steig ein, Schätzchen."),
    Z("—Del! My family is landing at half past four.", "¡Del! Mi familia aterriza a las cuatro y media.", "Del! Meine Familie landet um halb fünf."),
    N("Su móvil vibró. Un mensaje de Dan, en mayúsculas: «HUGE BACKUP ON THE FREEWAY!!! TAKE SURFACE STREETS!!!»",
      "Ihr Handy vibrierte. Eine Nachricht von Dan, in Großbuchstaben: »HUGE BACKUP ON THE FREEWAY!!! TAKE SURFACE STREETS!!!«"),
    Z("—My flatmate says there's a backup on the freeway.", "Mi compañero de piso dice que hay un atasco en la autopista.", "Mein Mitbewohner sagt, auf der Autobahn ist ein Stau."),
    Z("—A backup on the freeway? Is he American?", "¿Un «backup» en la «freeway»? ¿Es americano?", "Ein »Backup« auf dem »Freeway«? Ist er Amerikaner?"),
    Z("—From Ohio.", "De Ohio.", "Aus Ohio."),
    Z("—Thought so. Here we call it a jam on the motorway, love. But he's right. Everyone's going home for Christmas. Want me to take the back streets?", "Me lo imaginaba. Aquí lo llamamos «jam» en la «motorway», cielo. Pero tiene razón. Todo el mundo vuelve a casa por Navidad. ¿Quieres que vaya por las calles de atrás?", "Dachte ich mir. Hier sagen wir dazu »jam« auf der »motorway«, Schätzchen. Aber er hat recht. Alle fahren über Weihnachten nach Hause. Soll ich durch die Nebenstraßen fahren?"),
    Z("—Is that actually faster?", "¿De verdad es más rápido?", "Ist das wirklich schneller?"),
    Z("—In this traffic, yes. Ten minutes less, easy.", "Con este tráfico, sí. Diez minutos menos, fácil.", "Bei diesem Verkehr, ja. Zehn Minuten weniger, locker."),
    Z("—Let's do that.", "Vamos por ahí.", "Machen wir das."),
    Z("—Nobody knows this way. Only me and the foxes.", "Nadie conoce este camino. Solo yo y los zorros.", "Diesen Weg kennt keiner. Nur ich und die Füchse."),
    N("Otro mensaje, ahora de su madre: una foto del control de pasaportes. Doscientas personas en fila, en silencio absoluto. «¿Esto es normal? Nadie se cuela. Nadie protesta. Me da miedo.»",
      "Noch eine Nachricht, diesmal von ihrer Mutter: ein Foto von der Passkontrolle. Zweihundert Menschen in einer Schlange, in völliger Stille. »Ist das normal? Keiner drängelt. Keiner beschwert sich. Mir ist das unheimlich.«"),
    Z("At ten to five, the cab stopped at Terminal two.", "A las cinco menos diez, el taxi paró en la terminal dos.", "Um zehn vor fünf hielt das Taxi am Terminal zwei."),
    Z("—Go on, love. I'll wait. I'm not going anywhere in this traffic.", "Venga, cielo. Te espero. Con este tráfico no voy a ninguna parte.", "Geh nur, Schätzchen. Ich warte. Bei dem Verkehr fahre ich sowieso nirgendwohin."),
    N("En la sala de llegadas: Mateo, que corrió hacia ella con una mochila más grande que él. Su madre, que lloraba y se reía a la vez. Y su padre, con una caja de cartón atada con cuerda que olía a azúcar a través del cartón.",
      "In der Ankunftshalle: Mateo, der mit einem Rucksack, größer als er selbst, auf sie zurannte. Ihre Mutter, die gleichzeitig weinte und lachte. Und ihr Vater mit einem Karton, mit Schnur verschnürt, der durch die Pappe hindurch nach Zucker roch."),
    Z("Her father was carrying a big box of pan dulce. Conchas. Forty of them. On the plane.", "Su padre llevaba una caja grande de pan dulce. Conchas. Cuarenta. En el avión.", "Ihr Vater trug eine große Kiste mexikanisches Süßgebäck. Conchas. Vierzig Stück. Im Flugzeug."),
    N("«Me dijeron que aquí el pan es triste», dijo su padre. «Vengo a ayudar.»",
      "»Man hat mir gesagt, das Brot hier ist traurig«, sagte ihr Vater. »Ich komme, um zu helfen.«"),
    Z("In the cab, Mateo looked at Del for a long time. Then he tried his school English.", "En el taxi, Mateo miró a Del un buen rato. Luego probó su inglés del colegio.", "Im Taxi sah Mateo Del lange an. Dann probierte er sein Schulenglisch aus."),
    Z("—Excuse me. Why are you on the wrong side?", "Perdone. ¿Por qué está usted en el lado equivocado?", "Entschuldigung. Warum sitzen Sie auf der falschen Seite?"),
    Z("—Wrong side? This is the right side, son. Everyone else is on the wrong side.", "¿El lado equivocado? Este es el lado correcto, chaval. Todos los demás están en el lado equivocado.", "Falsche Seite? Das ist die richtige Seite, Junge. Alle anderen sitzen auf der falschen."),
    N("Su padre se inclinó hacia delante. «Pídele un recibo. Para la contabilidad de la panadería.» — «Papá, esto no es de la panadería.» — «Todo es de la panadería.»",
      "Ihr Vater beugte sich vor. »Frag ihn nach einer Quittung. Für die Buchhaltung der Bäckerei.« – »Papa, das hat mit der Bäckerei nichts zu tun.« – »Alles hat mit der Bäckerei zu tun.«"),
    Z("—Del, could I get a receipt at the end? For my father's bakery.", "Del, ¿me puedes dar un recibo al final? Para la panadería de mi padre.", "Del, kann ich am Ende eine Quittung bekommen? Für die Bäckerei meines Vaters."),
    Z("—For a bakery in Mexico? You got it, love.", "¿Para una panadería en México? Hecho, cielo.", "Für eine Bäckerei in Mexiko? Geht klar, Schätzchen."),
    Z("At the flat, her father gave Del a concha. Del looked at it.", "En el piso, su padre le dio a Del una concha. Del la miró.", "Vor der Wohnung gab ihr Vater Del eine Concha. Del betrachtete sie."),
    Z("—What's it called?", "¿Cómo se llama?", "Wie heißt das?"),
    Z("—A concha. It means “shell”.", "Concha. Significa «concha» de mar.", "Concha. Das heißt »Muschel«."),
    Z("Del took a bite and closed his eyes.", "Del le dio un mordisco y cerró los ojos.", "Del biss hinein und schloss die Augen."),
    Z("—Best shell I've ever had.", "La mejor concha que he comido en mi vida.", "Die beste Muschel, die ich je gegessen habe.")
  ]),

  // ── Station 12 · HOTEL (A2) ─────────────────────────────────────────
  S('aufbau', 12, 'hotel', "The heating isn't working",
    "Una noche fría en el hotel y una ducha fría para el padre. Sofía baja a recepción a quejarse… y no para de pedir perdón.",
    "Eine kalte Nacht im Hotel und eine kalte Dusche für den Vater. Sofía geht zur Rezeption, um sich zu beschweren … und entschuldigt sich ununterbrochen.",
  [
    Z("The family was staying in a small hotel in Camden Town, ten minutes from Sofía's flat.", "La familia se alojaba en un hotel pequeño de Camden Town, a diez minutos del piso de Sofía.", "Die Familie wohnte in einem kleinen Hotel in Camden Town, zehn Minuten von Sofías Wohnung entfernt."),
    N("El piso de Kentish Town era pequeño: tres habitaciones, un baño y la guitarra de Dan en todas partes. No cabían tres personas más y una caja de conchas.",
      "Die Wohnung in Kentish Town war klein: drei Zimmer, ein Bad und Dans Gitarre überall. Drei Personen mehr und eine Kiste Conchas passten da nicht hinein."),
    Z("At seven o'clock the next morning, Sofía's phone rang. It was her mother.", "A las siete de la mañana siguiente sonó el móvil de Sofía. Era su madre.", "Am nächsten Morgen um sieben klingelte Sofías Handy. Es war ihre Mutter."),
    N("«Sofi, aquí no funciona la calefacción. Hace un frío horrible. Y no hay agua caliente. Tu padre se ha duchado con agua fría.» Detrás se oía a su padre, que cantaba una ranchera a todo volumen para no pensar en el agua.",
      "»Sofi, hier geht die Heizung nicht. Es ist schrecklich kalt. Und es gibt kein warmes Wasser. Dein Vater hat kalt geduscht.« Im Hintergrund hörte man ihren Vater, der in voller Lautstärke eine Ranchera sang, um nicht an das Wasser zu denken."),
    Z("Twenty minutes later, Sofía was at the front desk. Behind it stood a young man in a Christmas jumper. His name badge said OLIVER.", "Veinte minutos después, Sofía estaba en la recepción. Detrás había un chico joven con un jersey de Navidad. En su placa ponía OLIVER.", "Zwanzig Minuten später stand Sofía an der Rezeption. Dahinter stand ein junger Mann in einem Weihnachtspullover. Auf seinem Namensschild stand OLIVER."),
    Z("—Good morning. How can I help?", "Buenos días. ¿En qué puedo ayudarla?", "Guten Morgen. Wie kann ich helfen?"),
    Z("—Good morning. I'm so sorry to bother you, but my parents are in room 204, and the heating isn't working.", "Buenos días. Siento mucho molestarle, pero mis padres están en la habitación 204 y la calefacción no funciona.", "Guten Morgen. Es tut mir sehr leid, Sie zu stören, aber meine Eltern sind in Zimmer 204, und die Heizung funktioniert nicht."),
    Z("—Oh, I'm sorry to hear that. How long has it been out?", "Vaya, lo siento. ¿Desde cuándo no funciona?", "Oh, das tut mir leid. Seit wann ist sie ausgefallen?"),
    Z("—Since last night. Sorry. And there's no hot water either. Sorry.", "Desde anoche. Perdón. Y tampoco hay agua caliente. Perdón.", "Seit gestern Abend. Entschuldigung. Und es gibt auch kein warmes Wasser. Entschuldigung."),
    Z("—I can send someone up right away. Or I can move them to another room.", "Puedo mandar a alguien ahora mismo. O puedo cambiarlos a otra habitación.", "Ich kann sofort jemanden hinaufschicken. Oder ich kann ihnen ein anderes Zimmer geben."),
    N("Sofía tradujo por teléfono. Su madre ya lo había decidido: «Nos cambiamos. Y dile que quiero más toallas.» Mateo: «¿Hay alguna con tele grande?» Su padre no opinó. Seguía cantando.",
      "Sofía übersetzte am Telefon. Ihre Mutter hatte schon entschieden: »Wir ziehen um. Und sag ihm, ich will mehr Handtücher.« Mateo: »Gibt es eins mit großem Fernseher?« Ihr Vater sagte nichts. Er sang noch."),
    Z("—I'd rather move them, if that's possible. Sorry. Room 204 is very noisy, too. The bins are right under the window.", "Prefiero cambiarlos, si es posible. Perdón. Además, la 204 es muy ruidosa. Los cubos de basura están justo debajo de la ventana.", "Ich würde sie lieber umziehen lassen, wenn das möglich ist. Entschuldigung. Zimmer 204 ist außerdem sehr laut. Die Mülltonnen stehen direkt unter dem Fenster."),
    Z("—Of course. I'll give them room 305. It's quieter, it's at the back, and the heating works. I checked it myself.", "Por supuesto. Les doy la 305. Es más tranquila, da a la parte de atrás y la calefacción funciona. Lo he comprobado yo mismo.", "Selbstverständlich. Ich gebe ihnen Zimmer 305. Es ist ruhiger, es liegt nach hinten, und die Heizung funktioniert. Ich habe es selbst geprüft."),
    Z("—Thank you. And sorry, one more thing: there are only two towels, and they are three people.", "Gracias. Y perdón, otra cosa: solo hay dos toallas, y son tres personas.", "Danke. Und Entschuldigung, noch etwas: Es gibt nur zwei Handtücher, und sie sind zu dritt."),
    Z("—I'll let housekeeping know. And we're very sorry for the trouble.", "Se lo digo a las de limpieza. Y sentimos mucho las molestias.", "Ich sage der Zimmerreinigung Bescheid. Und die Unannehmlichkeiten tun uns sehr leid."),
    Z("—No, no, I'm sorry.", "No, no, perdone usted.", "Nein, nein, mir tut es leid."),
    Z("—No, really, we're sorry.", "No, de verdad, lo sentimos nosotros.", "Nein, wirklich, uns tut es leid."),
    N("Siguieron así un rato, como dos personas que se ceden el paso en una puerta estrecha y nunca pasa nadie. Al final ganó Oliver. Era inglés de nacimiento; tenía más práctica.",
      "So ging es eine Weile weiter, wie bei zwei Menschen, die sich an einer engen Tür gegenseitig den Vortritt lassen, und keiner geht durch. Am Ende gewann Oliver. Er war gebürtiger Engländer; er hatte mehr Übung."),
    N("Cuando Sofía se dio la vuelta, su madre estaba detrás de ella, con el abrigo encima del pijama. Lo había oído todo. Contaba con los dedos. «Nueve. Nueve veces “sorry”. ¿Desde cuándo pides perdón cuando la que pasa frío es tu madre?»",
      "Als Sofía sich umdrehte, stand ihre Mutter hinter ihr, den Mantel über dem Schlafanzug. Sie hatte alles gehört. Sie zählte an den Fingern. »Neun. Neunmal ›sorry‹. Seit wann entschuldigst du dich, wenn deine Mutter diejenige ist, die friert?«"),
    N("«Aquí es así, mamá. En Londres, “sorry” no quiere decir que tengas la culpa. Quiere decir: hay un problemita, seamos amables.»",
      "»Hier ist das so, Mama. In London heißt ›sorry‹ nicht, dass du schuld bist. Es heißt: Da ist ein kleines Problem, seien wir freundlich.«"),
    Z("Room 305 was smaller, but it was warm, and the water in the shower was hot.", "La habitación 305 era más pequeña, pero estaba caliente, y el agua de la ducha salía caliente.", "Zimmer 305 war kleiner, aber es war warm, und das Wasser in der Dusche war heiß."),
    Z("Her father stood under the hot water and sang the whole ranchera again, from the beginning. Slowly, this time.", "Su padre se metió bajo el agua caliente y volvió a cantar la ranchera entera, desde el principio. Esta vez, despacio.", "Ihr Vater stellte sich unter das heiße Wasser und sang die ganze Ranchera noch einmal von vorn. Diesmal langsam."),
    Z("On the front desk there was now a plate of mince pies. Mateo took one.", "En la recepción ahora había un plato de mince pies. Mateo cogió uno.", "Auf der Rezeption stand jetzt ein Teller mit Mince Pies. Mateo nahm einen."),
    Z("Sofía stopped him and turned to Oliver.", "Sofía lo paró y se volvió hacia Oliver.", "Sofía hielt ihn zurück und wandte sich an Oliver."),
    Z("—Sorry, do they have nuts in them?", "Perdone, ¿llevan frutos secos?", "Entschuldigung, sind da Nüsse drin?"),
    Z("—Some do. These have almonds.", "Algunos sí. Estos llevan almendras.", "Manche schon. Diese hier haben Mandeln."),
    Z("Mateo put the mince pie back on the plate, very carefully.", "Mateo dejó el mince pie en el plato, con mucho cuidado.", "Mateo legte den Mince Pie ganz vorsichtig auf den Teller zurück."),
    Z("—Sorry.", "Perdón.", "Entschuldigung."),
    N("Su madre lo miró a él, luego a Sofía. «Ya son dos.»",
      "Ihre Mutter sah ihn an, dann Sofía. »Jetzt sind es schon zwei.«")
  ]),

  // ── Station 13 · CAFÉ (A2) ──────────────────────────────────────────
  S('aufbau', 13, 'cafe', "Sorry to bother you",
    "En el café de la señora Georgiou nadie se queja. Pero el café del padre está frío, Mateo no puede comer frutos secos y la madre descubre el té con leche.",
    "Im Café von Mrs Georgiou beschwert sich niemand. Aber der Kaffee des Vaters ist kalt, Mateo verträgt keine Nüsse, und die Mutter entdeckt den Tee mit Milch.",
  [
    Z("That afternoon, Sofía took her family to Mrs Georgiou's café on the corner.", "Esa tarde, Sofía llevó a su familia al café de la señora Georgiou, en la esquina.", "An diesem Nachmittag nahm Sofía ihre Familie mit ins Café von Mrs Georgiou an der Ecke."),
    N("La señora Georgiou llevaba casi cuarenta años detrás de esa barra, con delantal blanco, el pelo gris recogido y una regla que nadie había escrito: en su café nadie se queja. En octubre, Dan había pedido un «refill» gratis, como en Ohio. Ella lo miró tres segundos y dijo: «This is Kentish Town, not Ohio.» Dan aún no se había recuperado.",
      "Mrs Georgiou stand seit fast vierzig Jahren hinter dieser Theke, mit weißer Schürze, hochgestecktem grauem Haar und einer Regel, die nirgends geschrieben stand: In ihrem Café beschwert sich niemand. Im Oktober hatte Dan um ein kostenloses »Refill« gebeten, wie in Ohio. Sie sah ihn drei Sekunden lang an und sagte: »This is Kentish Town, not Ohio.« Dan hatte sich noch immer nicht davon erholt."),
    Z("—So this is the family. Sit, sit. What can I get you?", "Así que esta es la familia. Sentaos, sentaos. ¿Qué os pongo?", "Das ist also die Familie. Setzen Sie sich, setzen Sie sich. Was darf ich Ihnen bringen?"),
    Z("—A coffee with milk for my father, a hot chocolate for Mateo and a tea for my mother, please.", "Un café con leche para mi padre, un chocolate caliente para Mateo y un té para mi madre, por favor.", "Einen Milchkaffee für meinen Vater, eine heiße Schokolade für Mateo und einen Tee für meine Mutter, bitte."),
    Z("—Tea. With milk, of course.", "Té. Con leche, claro.", "Tee. Mit Milch, natürlich."),
    N("Su madre puso cara de horror. En su casa, el té era de manzanilla, para el dolor de barriga, y sin nada. Sofía le tocó el brazo: «Pruébalo, mamá. Yo también lo odiaba. Ahora me tomo cuatro al día.»",
      "Ihre Mutter machte ein entsetztes Gesicht. Bei ihr zu Hause war Tee Kamillentee, gegen Bauchweh, und ohne alles. Sofía berührte ihren Arm: »Probier ihn, Mama. Ich habe ihn auch gehasst. Jetzt trinke ich vier am Tag.«"),
    N("Luego, la vitrina de las tartas. Mateo pegó la nariz al cristal y su madre se puso seria. Mateo es alérgico a los frutos secos. Desde que tenía cuatro años, la familia lee cada etiqueta dos veces.",
      "Dann die Kuchenvitrine. Mateo drückte die Nase an das Glas, und seine Mutter wurde ernst. Mateo ist allergisch gegen Nüsse. Seit er vier ist, liest die Familie jedes Etikett zweimal."),
    Z("—Mrs Georgiou, does the chocolate cake have nuts in it?", "Señora Georgiou, ¿la tarta de chocolate lleva frutos secos?", "Mrs Georgiou, sind im Schokoladenkuchen Nüsse?"),
    Z("—That one does. Walnuts. The carrot cake too.", "Esa sí. Nueces. Y la de zanahoria también.", "Da schon. Walnüsse. Im Karottenkuchen auch."),
    Z("—And the lemon cake?", "¿Y la de limón?", "Und im Zitronenkuchen?"),
    Z("—The lemon cake doesn't, though. Lemon, eggs, butter, sugar. That's all.", "La de limón, en cambio, no. Limón, huevos, mantequilla, azúcar. Nada más.", "Im Zitronenkuchen dagegen nicht. Zitrone, Eier, Butter, Zucker. Das ist alles."),
    Z("—Perfect. My brother is allergic. He'll take the lemon one.", "Perfecto. Mi hermano es alérgico. Él tomará la de limón.", "Perfekt. Mein Bruder ist allergisch. Er nimmt den Zitronenkuchen."),
    N("Entonces su padre bebió un sorbo de café. Hizo una mueca y susurró: «Está frío.» Sofía se quedó helada, como el café.",
      "Dann trank ihr Vater einen Schluck Kaffee. Er verzog das Gesicht und flüsterte: »Der ist kalt.« Sofía erstarrte, genau wie der Kaffee."),
    Z("Mrs Georgiou came back with the plates.", "La señora Georgiou volvió con los platos.", "Mrs Georgiou kam mit den Tellern zurück."),
    Z("—How's everything over here?", "¿Qué tal todo por aquí?", "Ist hier alles in Ordnung?"),
    Z("Sofía took a deep breath.", "Sofía respiró hondo.", "Sofía holte tief Luft."),
    Z("—Sorry to bother you, but… my father's coffee is cold.", "Siento molestarla, pero… el café de mi padre está frío.", "Entschuldigen Sie die Störung, aber … der Kaffee meines Vaters ist kalt."),
    N("Silencio. Un señor bajó el periódico. Dan, que acababa de abrir la puerta, se quedó en el umbral y no entró.",
      "Stille. Ein Herr ließ seine Zeitung sinken. Dan, der gerade die Tür geöffnet hatte, blieb in der Tür stehen und kam nicht herein."),
    Z("Mrs Georgiou touched the cup.", "La señora Georgiou tocó la taza.", "Mrs Georgiou fasste die Tasse an."),
    Z("—You're right. I'm so sorry. I'll get him a fresh one right away.", "Tienes razón. Lo siento mucho. Ahora mismo le traigo uno recién hecho.", "Du hast recht. Das tut mir sehr leid. Ich bringe ihm sofort einen frischen."),
    Z("She brought a fresh coffee, very hot, and a small plate with a biscuit in the shape of a ring.", "Trajo un café recién hecho, muy caliente, y un platito con una galleta en forma de anillo.", "Sie brachte einen frischen Kaffee, sehr heiß, und einen kleinen Teller mit einem Keks in Form eines Rings."),
    Z("—Koulourakia. My mother's recipe. For the boy. But let me double-check first.", "Koulourakia. La receta de mi madre. Para el chico. Pero déjame comprobarlo antes.", "Koulourakia. Das Rezept meiner Mutter. Für den Jungen. Aber lass mich das erst noch mal prüfen."),
    Z("She took an old notebook from the kitchen and read the recipe, line by line.", "Sacó un cuaderno viejo de la cocina y leyó la receta, línea a línea.", "Sie holte ein altes Heft aus der Küche und las das Rezept, Zeile für Zeile."),
    Z("—Flour, butter, sugar, eggs, orange. No nuts. None.", "Harina, mantequilla, azúcar, huevos, naranja. Sin frutos secos. Ninguno.", "Mehl, Butter, Zucker, Eier, Orange. Keine Nüsse. Keine einzige."),
    Z("Mateo ate it in two bites.", "Mateo se la comió en dos bocados.", "Mateo aß ihn in zwei Bissen."),
    Z("—One more, please?", "¿Otra, por favor?", "Noch einen, bitte?"),
    Z("—For you, two more. On the house.", "Para ti, dos más. Invita la casa.", "Für dich zwei. Geht aufs Haus."),
    Z("At the door, Dan finally came in.", "Dan, en la puerta, entró por fin.", "Dan kam endlich zur Tür herein."),
    Z("—You complained to Mrs Georgiou. And you're still alive.", "Te has quejado a la señora Georgiou. Y sigues viva.", "Du hast dich bei Mrs Georgiou beschwert. Und du lebst noch."),
    N("Y su madre, sin decir nada, se terminó el té con leche. Todo. Luego levantó la taza vacía hacia la señora Georgiou y dijo su primera palabra en inglés: «More.» Sofía lo apuntó en su lista. Otra víctima.",
      "Und ihre Mutter trank, ohne ein Wort zu sagen, den Tee mit Milch aus. Ganz. Dann hob sie die leere Tasse in Richtung Mrs Georgiou und sagte ihr erstes englisches Wort: »More.« Sofía notierte es auf ihrer Liste. Ein weiteres Opfer.")
  ]),

  // ── Station 14 · WEGBESCHREIBUNG (A2) ───────────────────────────────
  S('aufbau', 14, 'wegbeschreibung', "You can't miss it",
    "Dos turistas de Texas se pierden en Bloomsbury y le preguntan a Sofía por el British Museum. Ella les explica el camino delante de toda su familia.",
    "Zwei Touristen aus Texas verlaufen sich in Bloomsbury und fragen Sofía nach dem British Museum. Sie erklärt den Weg – vor ihrer ganzen Familie.",
  [
    Z("On Monday, Sofía showed her family where she worked: an old building in Bloomsbury with a blue door and too many stairs.", "El lunes, Sofía le enseñó a su familia dónde trabajaba: un edificio antiguo en Bloomsbury, con una puerta azul y demasiadas escaleras.", "Am Montag zeigte Sofía ihrer Familie, wo sie arbeitete: ein altes Haus in Bloomsbury mit einer blauen Tür und zu vielen Treppen."),
    N("Arriba olía a papel y a café. En la mesa de Sofía estaba la portada del libro de recetas, con la tarta de limón. Ya no parecía triste. Su padre la miró mucho rato, como panadero, y dijo: «Le falta azúcar por encima.» Tenía razón. Sofía lo cambió esa misma tarde.",
      "Oben roch es nach Papier und Kaffee. Auf Sofías Tisch lag das Cover des Kochbuchs mit dem Zitronenkuchen. Er sah nicht mehr traurig aus. Ihr Vater betrachtete ihn lange, als Bäcker, und sagte: »Oben fehlt Puderzucker.« Er hatte recht. Sofía änderte es noch am selben Nachmittag."),
    Z("Outside, on the pavement, a man and a woman were looking at a map. They had big coats, big smiles and one very big camera.", "Fuera, en la acera, un hombre y una mujer miraban un mapa. Tenían abrigos grandes, sonrisas grandes y una cámara muy grande.", "Draußen auf dem Gehweg schauten ein Mann und eine Frau auf einen Stadtplan. Sie hatten große Mäntel, ein breites Lächeln und eine sehr große Kamera."),
    Z("—Sorry, you look a little lost. Need a hand?", "Perdonen, parecen un poco perdidos. ¿Les echo una mano?", "Entschuldigung, Sie sehen ein bisschen verloren aus. Brauchen Sie Hilfe?"),
    N("Sofía se oyó a sí misma y casi se rió. Hacía dos meses, la perdida era ella.",
      "Sofía hörte sich selbst und musste fast lachen. Vor zwei Monaten war sie diejenige gewesen, die sich verlaufen hatte."),
    Z("—Yes, ma'am! We're from Austin, Texas. How do we get to the British Museum from here?", "¡Sí, señora! Somos de Austin, Texas. ¿Cómo llegamos al British Museum desde aquí?", "Ja, Ma'am! Wir sind aus Austin, Texas. Wie kommen wir von hier zum British Museum?"),
    N("Detrás de ella, su familia escuchaba como se escucha a una hija en un examen. Su madre no entendía nada, pero movía los labios con ella, palabra por palabra.",
      "Hinter ihr hörte ihre Familie zu, wie man einer Tochter bei einer Prüfung zuhört. Ihre Mutter verstand kein Wort, aber sie bewegte die Lippen mit, Wort für Wort."),
    Z("—It's not far. Head down to the lights and cross over.", "No está lejos. Bajen hasta el semáforo y crucen.", "Es ist nicht weit. Gehen Sie runter bis zur Ampel und dann über die Straße."),
    Z("—And then what? Is there a traffic circle? I hate traffic circles.", "¿Y luego qué? ¿Hay un «traffic circle»? Odio las rotondas.", "Und dann? Gibt es einen »Traffic Circle«? Ich hasse Kreisverkehre."),
    Z("—A roundabout? No, sorry, no roundabout. Just keep going straight on.", "¿Una rotonda? No, lo siento, no hay rotonda. Sigan todo recto.", "Einen Kreisverkehr? Nein, tut mir leid, keinen Kreisverkehr. Gehen Sie einfach geradeaus weiter."),
    Z("—Sorry, how far?", "Perdone, ¿hasta dónde?", "Entschuldigung, wie weit?"),
    Z("—Sorry. Until you see a little bookshop with a green door. Then turn left. The museum is across from the bookshop.", "Perdón. Hasta que vean una librería pequeña con una puerta verde. Allí giren a la izquierda. El museo está enfrente de la librería.", "Entschuldigung. Bis Sie eine kleine Buchhandlung mit einer grünen Tür sehen. Dort biegen Sie links ab. Das Museum liegt gegenüber der Buchhandlung."),
    Z("—Can we walk there?", "¿Se puede ir andando?", "Können wir zu Fuß hingehen?"),
    Z("—Yes, it's about fifteen minutes on foot. You can't miss it. It looks like a Greek temple.", "Sí, son unos quince minutos a pie. No tiene pérdida. Parece un templo griego.", "Ja, es sind etwa fünfzehn Minuten zu Fuß. Sie können es nicht verfehlen. Es sieht aus wie ein griechischer Tempel."),
    Z("—Thank you, honey. Are you from London?", "Gracias, cielo. ¿Es usted de Londres?", "Danke, Schätzchen. Sind Sie aus London?"),
    Z("—No, sorry. I'm from Mexico. From Jalisco.", "No, lo siento. Soy de México. De Jalisco.", "Nein, tut mir leid. Ich bin aus Mexiko. Aus Jalisco."),
    Z("—Jalisco! There's a Mexican restaurant on our street. Best tacos in Texas.", "¡Jalisco! En nuestra calle hay un restaurante mexicano. Los mejores tacos de Texas.", "Jalisco! In unserer Straße gibt es ein mexikanisches Restaurant. Die besten Tacos in Texas."),
    Z("—Well, you sound like a real Londoner. You said sorry four times.", "Pues parece usted londinense de verdad. Ha dicho «sorry» cuatro veces.", "Na, Sie klingen wie eine echte Londonerin. Sie haben viermal »sorry« gesagt."),
    N("Su familia lo había visto todo desde la puerta azul. «¿Qué les dijiste?», preguntó su padre. «Que sigan recto y que no tiene pérdida.» — «¿Y por qué te pidieron perdón?» — «No me lo pidieron, papá. Se lo pedí yo.» Mateo levantó cuatro dedos. Había contado.",
      "Ihre Familie hatte alles von der blauen Tür aus beobachtet. »Was hast du ihnen gesagt?«, fragte ihr Vater. »Dass sie geradeaus gehen sollen und es nicht verfehlen können.« – »Und warum haben sie sich entschuldigt?« – »Haben sie nicht, Papa. Das war ich.« Mateo hielt vier Finger hoch. Er hatte mitgezählt."),
    Z("At the corner, the two Texans stopped, looked at the map again and turned right.", "En la esquina, los dos texanos se pararon, volvieron a mirar el mapa y giraron a la derecha.", "An der Ecke blieben die beiden Texaner stehen, schauten noch einmal auf den Plan und bogen rechts ab."),
    Z("Sofía ran after them down the street.", "Sofía corrió detrás de ellos por la calle.", "Sofía rannte ihnen die Straße hinunter hinterher."),
    Z("—Sorry! Your other right! I mean, left!", "¡Perdón! ¡La otra derecha! ¡Quiero decir, la izquierda!", "Entschuldigung! Die andere Rechte! Ich meine: links!"),
    N("Mateo levantó la mano entera. Cinco.",
      "Mateo hob die ganze Hand. Fünf."),
    Z("That evening, the Texans sent a photo to Sofía's phone: the two of them in front of a Greek temple, with very big smiles.", "Esa noche, los texanos le mandaron una foto al móvil: los dos delante de un templo griego, con sonrisas enormes.", "Am Abend schickten die Texaner ein Foto auf Sofías Handy: die beiden vor einem griechischen Tempel, mit einem riesigen Lächeln."),
    Z("Under the photo, it said: “We didn't miss it. Sorry!”", "Debajo de la foto ponía: «No tenía pérdida. ¡Sorry!».", "Unter dem Foto stand: »Wir haben es nicht verfehlt. Sorry!«")
  ]),

  // ── Station 15 · EINKAUFEN (A2) ─────────────────────────────────────
  S('aufbau', 15, 'einkaufen', "One size down",
    "Sofía le regaló a su padre un jersey de rebajas, pero le queda enorme. En la tienda lo cambian… y el padre dice su primera frase en inglés.",
    "Sofía hat ihrem Vater einen reduzierten Pullover geschenkt, aber er ist ihm viel zu groß. Im Laden wird er umgetauscht … und der Vater sagt seinen ersten englischen Satz.",
  [
    Z("In London, Sofía's father was always cold.", "En Londres, el padre de Sofía siempre tenía frío.", "In London fror Sofías Vater ständig."),
    N("Llevaba veinte años trabajando al lado de un horno, desde las cuatro de la mañana. Para él, el frío era una teoría. En Londres descubrió que era una realidad, y que entraba por el cuello.",
      "Er arbeitete seit zwanzig Jahren ab vier Uhr morgens neben einem Backofen. Für ihn war Kälte eine Theorie. In London entdeckte er, dass sie Wirklichkeit war und durch den Kragen hereinkam."),
    Z("So Sofía gave him an early Christmas present: a grey and blue jumper. It was on sale.", "Así que Sofía le hizo un regalo de Navidad adelantado: un jersey gris y azul. Estaba de rebajas.", "Also schenkte Sofía ihm ein vorgezogenes Weihnachtsgeschenk: einen grau-blauen Pullover. Er war im Angebot."),
    Z("Dan saw it and whistled.", "Dan lo vio y silbó.", "Dan sah ihn und pfiff."),
    Z("—Nice sweater, man!", "¡Bonito suéter, tío!", "Schöner Sweater, Mann!"),
    N("Su padre la miró. «¿Suéter? Tú dijiste jumper.» — «Las dos cosas, papá. Dan dice sweater porque es de Ohio. Aquí se dice jumper. El jersey es el mismo; el país, no.»",
      "Ihr Vater sah sie an. »Sweater? Du hast doch jumper gesagt.« – »Beides, Papa. Dan sagt sweater, weil er aus Ohio ist. Hier sagt man jumper. Der Pullover ist derselbe, das Land nicht.«"),
    N("El problema era otro. El jersey le llegaba casi a las rodillas, y las mangas le tapaban las manos. Mateo dijo que parecía un fantasma muy triste.",
      "Das Problem war ein anderes. Der Pullover reichte ihm fast bis zu den Knien, und die Ärmel bedeckten seine Hände. Mateo sagte, er sehe aus wie ein sehr trauriges Gespenst."),
    Z("On Tuesday they went back to the shop together.", "El martes volvieron juntos a la tienda.", "Am Dienstag gingen sie zusammen zurück in den Laden."),
    Z("—Hi there. What can I help you with?", "Hola. ¿En qué puedo ayudarles?", "Hallo. Wobei kann ich Ihnen helfen?"),
    Z("—Hi. I bought this jumper last week, but it's too big for my father.", "Hola. Compré este jersey la semana pasada, pero a mi padre le queda grande.", "Hallo. Ich habe diesen Pullover letzte Woche gekauft, aber er ist meinem Vater zu groß."),
    Z("—No problem. Do you have the receipt?", "No hay problema. ¿Tiene el tique?", "Kein Problem. Haben Sie den Kassenbon?"),
    Z("—Yes, right here. Can I exchange it?", "Sí, aquí está. ¿Puedo cambiarlo?", "Ja, hier. Kann ich ihn umtauschen?"),
    Z("—Of course. What size does he need?", "Por supuesto. ¿Qué talla necesita?", "Natürlich. Welche Größe braucht er?"),
    Z("—One size down, I think. Can he try it on?", "Una talla menos, creo. ¿Se lo puede probar?", "Eine Nummer kleiner, glaube ich. Kann er ihn anprobieren?"),
    Z("—Sure. The fitting rooms are at the back, on the left.", "Claro. Los probadores están al fondo, a la izquierda.", "Klar. Die Umkleidekabinen sind hinten links."),
    Z("There was a queue for the fitting rooms, of course. Five people, very quiet.", "Había cola para los probadores, claro. Cinco personas, muy calladas.", "Vor den Umkleidekabinen gab es natürlich eine Schlange. Fünf Leute, ganz still."),
    N("Su padre fue directo a la primera cortina. Sofía lo agarró del brazo y lo devolvió al final de la cola, despacio, como se devuelve un libro a su estante.",
      "Ihr Vater ging direkt auf den ersten Vorhang zu. Sofía hielt ihn am Arm fest und brachte ihn langsam zurück ans Ende der Schlange, so wie man ein Buch an seinen Platz im Regal zurückstellt."),
    N("Mientras esperaban, Mateo le habló a su padre al oído. En el avión le había enseñado una frase en inglés. «Significa “me queda bien”», le había dicho. Su padre la había repetido sobre el Atlántico durante once horas.",
      "Während sie warteten, flüsterte Mateo seinem Vater etwas ins Ohr. Im Flugzeug hatte er ihm einen englischen Satz beigebracht. »Das heißt ›passt mir gut‹«, hatte er gesagt. Ihr Vater hatte ihn elf Stunden lang über dem Atlantik wiederholt."),
    Z("Her father went into the fitting room. Two minutes later he came out, turned around slowly and said, very loudly:", "Su padre entró en el probador. Dos minutos después salió, se dio la vuelta despacio y dijo, muy alto:", "Ihr Vater ging in die Kabine. Zwei Minuten später kam er heraus, drehte sich langsam um und sagte sehr laut:"),
    Z("—I am very handsome.", "Soy muy guapo.", "Ich bin sehr gutaussehend."),
    Z("The shop assistant smiled.", "La dependienta sonrió.", "Die Verkäuferin lächelte."),
    Z("—You are, sir. And it fits perfectly.", "Lo es, señor. Y le queda perfecto.", "Das sind Sie. Und er passt perfekt."),
    N("Sofía miró a Mateo. Mateo miró al techo. «Casi es lo mismo», murmuró.",
      "Sofía sah Mateo an. Mateo sah an die Decke. »Ist doch fast dasselbe«, murmelte er."),
    Z("—Would you like a bag?", "¿Quiere una bolsa?", "Möchten Sie eine Tüte?"),
    Z("—No, thank you. He wants to wear it.", "No, gracias. Se lo quiere llevar puesto.", "Nein, danke. Er will ihn gleich anbehalten."),
    Z("Her father wore the jumper out of the shop, down the street and all the way home.", "Su padre salió de la tienda con el jersey puesto, bajó la calle y fue así hasta casa.", "Ihr Vater trug den Pullover aus dem Laden, die Straße hinunter und den ganzen Weg nach Hause."),
    Z("On the way, he said his new sentence to a bus driver, a policeman and Mrs Okafor. Everyone agreed with him.", "Por el camino le dijo su frase nueva a un conductor de autobús, a un policía y a la señora Okafor. Todos le dieron la razón.", "Unterwegs sagte er seinen neuen Satz zu einem Busfahrer, einem Polizisten und zu Mrs Okafor. Alle gaben ihm recht.")
  ]),

  // ── Station 16 · WETTER (A2) ────────────────────────────────────────
  S('aufbau', 16, 'wetter', "Just in case",
    "¿Hyde Park el sábado? Depende del tiempo. La previsión dice una cosa, las palomas de la señora Okafor otra… o quizá la misma.",
    "Hyde Park am Samstag? Kommt aufs Wetter an. Der Wetterbericht sagt das eine, die Tauben von Mrs Okafor etwas anderes … oder vielleicht dasselbe.",
  [
    Z("On Thursday evening, everyone was in the kitchen of the flat. Dan had his guitar, Priya had her laptop, and Sofía's father had his new jumper.", "El jueves por la noche estaban todos en la cocina del piso. Dan tenía su guitarra, Priya su portátil y el padre de Sofía su jersey nuevo.", "Am Donnerstagabend waren alle in der Küche der Wohnung. Dan hatte seine Gitarre, Priya ihren Laptop und Sofías Vater seinen neuen Pullover."),
    Z("Dan had an idea.", "Dan tuvo una idea.", "Dan hatte eine Idee."),
    Z("—Want to hit the lake on Saturday?", "¿Os apetece ir al lago el sábado?", "Lust, am Samstag an den See zu gehen?"),
    Z("—Which lake?", "¿Qué lago?", "Welcher See?"),
    Z("—The Serpentine. It's a lake in Hyde Park. It's shaped like a snake.", "El Serpentine. Es un lago en Hyde Park. Tiene forma de serpiente.", "Der Serpentine. Das ist ein See im Hyde Park. Er hat die Form einer Schlange."),
    Z("—It depends on the weather. Did you check the forecast?", "Depende del tiempo. ¿Habéis mirado la previsión?", "Das hängt vom Wetter ab. Habt ihr den Wetterbericht angeschaut?"),
    Z("Priya checked.", "Priya lo miró.", "Priya schaute nach."),
    Z("—It's supposed to rain in the morning. Showers.", "Dicen que va a llover por la mañana. Chubascos.", "Am Vormittag soll es regnen. Schauer."),
    Z("—What about the afternoon?", "¿Y por la tarde?", "Und am Nachmittag?"),
    Z("—Should clear up. Sunny by two or so.", "Debería despejarse. Sol hacia las dos, más o menos.", "Es sollte aufklaren. Gegen zwei Sonne, ungefähr."),
    Z("—Let's go in the afternoon, then. I'll bring a jacket, just in case.", "Entonces vamos por la tarde. Yo llevo una chaqueta, por si acaso.", "Dann gehen wir am Nachmittag. Ich nehme eine Jacke mit, für alle Fälle."),
    N("Su madre no se fiaba. En Jalisco, si llueve por la mañana, llueve todo el día, y punto. En Londres, le había explicado Sofía, el tiempo cambia cuatro veces en una hora y nunca pide perdón. Es lo único en Inglaterra que no pide perdón.",
      "Ihre Mutter traute dem Ganzen nicht. In Jalisco gilt: Wenn es morgens regnet, regnet es den ganzen Tag, Punkt. In London, hatte Sofía ihr erklärt, ändert sich das Wetter viermal in der Stunde und entschuldigt sich nie. Es ist das Einzige in England, das sich nie entschuldigt."),
    Z("Then Sofía said the most important sentence in the house:", "Entonces Sofía dijo la frase más importante de la casa:", "Dann sagte Sofía den wichtigsten Satz im ganzen Haus:"),
    Z("—Let's ask Mrs Okafor.", "Vamos a preguntarle a la señora Okafor.", "Fragen wir Mrs Okafor."),
    N("La señora Okafor vivía en la planta baja. Llevaba, también en casa, su gorro de lana morado, y siete palomas se sentaban cada día en el muro delante de su ventana. No eran suyas. Pero trabajaban para ella.",
      "Mrs Okafor wohnte im Erdgeschoss. Sie trug, auch im Haus, ihre lila Wollmütze, und sieben Tauben saßen jeden Tag auf der Mauer vor ihrem Fenster. Es waren nicht ihre. Aber sie arbeiteten für sie."),
    Z("—Good evening, Mrs Okafor. What do the pigeons say about Saturday?", "Buenas noches, señora Okafor. ¿Qué dicen las palomas del sábado?", "Guten Abend, Mrs Okafor. Was sagen die Tauben über Samstag?"),
    Z("Mrs Okafor looked at the pigeons for a long time.", "La señora Okafor miró a las palomas un buen rato.", "Mrs Okafor betrachtete die Tauben lange."),
    Z("—They are sitting high today, on the roof. That means showers in the morning. It will clear up after lunch.", "Hoy están sentadas arriba, en el tejado. Eso quiere decir chubascos por la mañana. Después de comer se despejará.", "Heute sitzen sie oben, auf dem Dach. Das bedeutet Schauer am Vormittag. Nach dem Mittagessen klart es auf."),
    Z("—That's what the forecast says.", "Eso es lo que dice la previsión.", "Genau das sagt auch der Wetterbericht."),
    Z("—The forecast copies my pigeons, darling.", "La previsión copia a mis palomas, querida.", "Der Wetterbericht schreibt bei meinen Tauben ab, meine Liebe."),
    N("Su madre quiso contribuir. En su pueblo, dijo, la abuela miraba las hormigas: si caminan en fila, va a llover. Sofía tradujo.",
      "Ihre Mutter wollte auch etwas beitragen. In ihrem Dorf, sagte sie, habe die Großmutter auf die Ameisen geschaut: Wenn sie in einer Reihe laufen, wird es regnen. Sofía übersetzte."),
    Z("—Ants in a line! Then in London it rains every day. Everybody here walks in a line.", "¡Hormigas en fila! Entonces en Londres llueve todos los días. Aquí todo el mundo va en fila.", "Ameisen in einer Reihe! Dann regnet es in London jeden Tag. Hier laufen alle in einer Reihe."),
    Z("On Saturday morning it rained. The family stayed in, drank tea with milk and ate conchas.", "El sábado por la mañana llovió. La familia se quedó en casa, tomó té con leche y comió conchas.", "Am Samstagvormittag regnete es. Die Familie blieb zu Hause, trank Tee mit Milch und aß Conchas."),
    Z("At ten past two, the sun came out over the Serpentine. On the water there were swans, ducks and — in December — three old men in swimming costumes.", "A las dos y diez salió el sol sobre el Serpentine. En el agua había cisnes, patos y —en diciembre— tres señores mayores en bañador.", "Um zehn nach zwei kam über dem Serpentine die Sonne heraus. Auf dem Wasser gab es Schwäne, Enten und – im Dezember – drei alte Herren in Badehosen."),
    N("Su padre, con su jersey nuevo debajo del abrigo y una bufanda de Dan, los miró con la boca abierta. Él llevaba tres capas y seguía temblando.",
      "Ihr Vater, mit dem neuen Pullover unter dem Mantel und einem Schal von Dan, starrte sie mit offenem Mund an. Er trug drei Schichten und zitterte trotzdem."),
    Z("Mateo could not believe it.", "Mateo no se lo podía creer.", "Mateo konnte es nicht glauben."),
    Z("—Aren't they cold?", "¿No tienen frío?", "Ist denen nicht kalt?"),
    Z("Dan laughed.", "Dan se rió.", "Dan lachte."),
    Z("—They're British. They're always cold. They just don't say it.", "Son británicos. Siempre tienen frío. Solo que no lo dicen.", "Das sind Briten. Denen ist immer kalt. Sie sagen es nur nicht."),
    N("Su madre no necesitó la chaqueta. La llevó todo el día en el brazo, por si acaso, como llevan los ingleses el paraguas: no para usarlo, sino para tener razón.",
      "Ihre Mutter brauchte die Jacke nicht. Sie trug sie den ganzen Tag über dem Arm, für alle Fälle, so wie die Engländer ihren Regenschirm tragen: nicht, um ihn zu benutzen, sondern um recht zu behalten.")
  ]),

  // ── Station 17 · BAHNHOF (A2) ───────────────────────────────────────
  S('aufbau', 17, 'bahnhof', "Running late",
    "Priya tiene un plan para ir a Windsor, en tres colores. El tren no lo ha leído. Una hora en un andén helado… y de pronto, villancicos.",
    "Priya hat einen Plan für Windsor, in drei Farben. Der Zug hat ihn nicht gelesen. Eine Stunde auf einem eisigen Bahnsteig … und plötzlich Weihnachtslieder.",
  [
    Z("On Sunday, Priya had a plan. Priya always had a plan. This one was a spreadsheet in three colours.", "El domingo, Priya tenía un plan. Priya siempre tenía un plan. Este era una hoja de cálculo en tres colores.", "Am Sonntag hatte Priya einen Plan. Priya hatte immer einen Plan. Dieser war eine Tabelle in drei Farben."),
    Z("—Paddington at ten forty. Change at Slough. Windsor at eleven thirty. Castle at twelve. Lunch at two.", "Paddington a las diez y cuarenta. Cambio en Slough. Windsor a las once y media. Castillo a las doce. Comida a las dos.", "Paddington um zehn Uhr vierzig. Umsteigen in Slough. Windsor um halb zwölf. Schloss um zwölf. Mittagessen um zwei."),
    Z("But at Paddington, the board said DELAYED. Their train was running twenty minutes late.", "Pero en Paddington, el panel decía RETRASADO. Su tren llevaba veinte minutos de retraso.", "Aber in Paddington stand auf der Anzeigetafel VERSPÄTET. Ihr Zug hatte zwanzig Minuten Verspätung."),
    N("Priya miró la pantalla como se mira a un compañero de trabajo que no ha hecho su parte. Luego se puso en la cola de la ventanilla. Once personas, en silencio. Su padre buscó con los ojos un atajo hasta el mostrador. Sofía lo cogió de la manga sin decir nada. Ya era la segunda vez esa semana.",
      "Priya sah die Anzeige an, wie man einen Kollegen ansieht, der seinen Teil der Arbeit nicht gemacht hat. Dann stellte sie sich am Schalter an. Elf Leute, schweigend. Ihr Vater suchte mit den Augen eine Abkürzung zum Schalter. Sofía hielt ihn wortlos am Ärmel fest. Es war schon das zweite Mal in dieser Woche."),
    Z("—Next. What can I do for you?", "Siguiente. ¿Qué puedo hacer por ustedes?", "Der Nächste. Was kann ich für Sie tun?"),
    Z("—Our train is running twenty minutes late.", "Nuestro tren lleva veinte minutos de retraso.", "Unser Zug hat zwanzig Minuten Verspätung."),
    Z("—Sorry about that. When's your connection?", "Lo siento. ¿A qué hora es su enlace?", "Das tut mir leid. Wann geht Ihr Anschluss?"),
    Z("—In Slough, at twenty-five past eleven.", "En Slough, a las once y veinticinco.", "In Slough, um elf Uhr fünfundzwanzig."),
    Z("—That's tight. The connection won't wait for you.", "Va muy justo. El enlace no les va a esperar.", "Das wird knapp. Der Anschluss wartet nicht auf Sie."),
    Z("—And if we miss it?", "¿Y si lo perdemos?", "Und wenn wir ihn verpassen?"),
    Z("—Then take the next one. Your ticket is still valid. No extra fee.", "Entonces cojan el siguiente. Su billete sigue siendo válido. Sin cargo extra.", "Dann nehmen Sie den nächsten. Ihre Fahrkarte bleibt gültig. Ohne Aufpreis."),
    Z("At Slough they ran down the stairs and up the stairs. The doors of the little train to Windsor closed in front of them.", "En Slough bajaron las escaleras corriendo y las subieron corriendo. Las puertas del trenecito a Windsor se cerraron delante de ellos.", "In Slough rannten sie die Treppe hinunter und die Treppe hinauf. Die Türen des kleinen Zuges nach Windsor schlossen sich vor ihnen."),
    Z("They missed it by one minute. The next train was in fifty minutes.", "Lo perdieron por un minuto. El siguiente tren salía en cincuenta minutos.", "Sie verpassten ihn um eine Minute. Der nächste Zug fuhr in fünfzig Minuten."),
    Z("The platform was grey, cold and very windy.", "El andén era gris, frío y hacía mucho viento.", "Der Bahnsteig war grau, kalt und sehr windig."),
    N("«En Ohio iríamos en coche», dijo Dan. «En Bangalore todavía estaríamos en el atasco», dijo Priya. Su madre no dijo nada: abrió el bolso y sacó seis conchas. Su madre llevaba conchas a todas partes, como otras madres llevan pañuelos.",
      "»In Ohio würden wir einfach Auto fahren«, sagte Dan. »In Bengaluru stünden wir noch im Stau«, sagte Priya. Ihre Mutter sagte nichts: Sie öffnete ihre Handtasche und holte sechs Conchas heraus. Ihre Mutter hatte überall Conchas dabei, so wie andere Mütter Taschentücher."),
    Z("Then a group of schoolchildren in red hats came onto the platform with their teacher. They were going to sing in Windsor.", "Entonces llegó al andén un grupo de escolares con gorros rojos y su profesora. Iban a cantar a Windsor.", "Dann kam eine Gruppe Schulkinder mit roten Mützen und ihrer Lehrerin auf den Bahnsteig. Sie wollten in Windsor singen."),
    Z("The teacher looked at the cold faces on the platform.", "La profesora miró las caras de frío del andén.", "Die Lehrerin sah die verfrorenen Gesichter auf dem Bahnsteig an."),
    Z("—Shall we practise, children?", "¿Ensayamos, niños?", "Sollen wir üben, Kinder?"),
    Z("They sang “Silent Night”. Softly, and a little out of tune.", "Cantaron «Noche de paz». Bajito, y un poco desafinados.", "Sie sangen »Stille Nacht«. Leise und ein bisschen schief."),
    N("Su madre conocía la canción. Cantó con ellos, en español: «Noche de paz, noche de amor…». Los niños se callaron un momento para escucharla. Luego siguieron. Dos idiomas, la misma melodía, y de repente el andén estaba un poco menos frío.",
      "Ihre Mutter kannte das Lied. Sie sang mit, auf Spanisch: »Noche de paz, noche de amor …« Die Kinder verstummten einen Moment, um ihr zuzuhören. Dann sangen sie weiter. Zwei Sprachen, dieselbe Melodie, und plötzlich war der Bahnsteig ein bisschen weniger kalt."),
    Z("The next train came on time. Nobody said a word about the fifty minutes.", "El siguiente tren llegó puntual. Nadie dijo ni una palabra sobre los cincuenta minutos.", "Der nächste Zug kam pünktlich. Niemand verlor ein Wort über die fünfzig Minuten."),
    Z("In the train, Priya looked sadly at her spreadsheet.", "En el tren, Priya miró su hoja de cálculo con tristeza.", "Im Zug betrachtete Priya traurig ihre Tabelle."),
    Z("—We missed the connection.", "Hemos perdido el enlace.", "Wir haben den Anschluss verpasst."),
    Z("Sofía translated for her mother. Her mother answered in Spanish, and Sofía translated back:", "Sofía se lo tradujo a su madre. Su madre contestó en español, y Sofía lo tradujo de vuelta:", "Sofía übersetzte es für ihre Mutter. Ihre Mutter antwortete auf Spanisch, und Sofía übersetzte zurück:"),
    Z("—My mother says we didn't miss a train. We caught a concert.", "Mi madre dice que no hemos perdido un tren. Hemos pillado un concierto.", "Meine Mutter sagt, wir haben keinen Zug verpasst. Wir haben ein Konzert erwischt.")
  ]),

  // ── Station 18 · RESTAURANT (A2) ────────────────────────────────────
  S('aufbau', 18, 'restaurant', "Plenty for two",
    "Un pub en Windsor, un fuego, un perro y un asado de domingo. El padre panadero descubre el Yorkshire pudding, y Sofía paga con su propio sueldo.",
    "Ein Pub in Windsor, ein Kaminfeuer, ein Hund und ein Sonntagsbraten. Der Bäckervater entdeckt den Yorkshire Pudding, und Sofía zahlt mit ihrem eigenen Gehalt.",
  [
    Z("After the castle, cold and hungry, they found a pub on a small street. It had a fire, a low ceiling and a dog asleep by the door.", "Después del castillo, con frío y con hambre, encontraron un pub en una calle pequeña. Tenía chimenea, el techo bajo y un perro dormido junto a la puerta.", "Nach dem Schloss, verfroren und hungrig, fanden sie ein Pub in einer kleinen Straße. Es hatte einen Kamin, eine niedrige Decke und einen Hund, der neben der Tür schlief."),
    Z("—A table for six, please.", "Una mesa para seis, por favor.", "Einen Tisch für sechs, bitte."),
    Z("The waiter gave them the table next to the fire. Her father sat down and did not want to move ever again.", "El camarero les dio la mesa junto a la chimenea. Su padre se sentó y no quiso moverse nunca más.", "Der Kellner gab ihnen den Tisch am Kamin. Ihr Vater setzte sich und wollte nie wieder aufstehen."),
    Z("—Have you all decided, or do you need another minute?", "¿Ya lo tienen decidido o necesitan otro minuto?", "Haben Sie sich entschieden, oder brauchen Sie noch eine Minute?"),
    Z("—What's the house specialty?", "¿Cuál es la especialidad de la casa?", "Was ist die Spezialität des Hauses?"),
    Z("—The Sunday roast. Roast beef, potatoes, vegetables and Yorkshire pudding. It's rich, but it's worth it.", "El asado del domingo. Rosbif, patatas, verduras y Yorkshire pudding. Es contundente, pero merece la pena.", "Der Sonntagsbraten. Roastbeef, Kartoffeln, Gemüse und Yorkshire Pudding. Er ist deftig, aber er lohnt sich."),
    N("Su padre oyó «pudding» y se puso contento: un postre. Luego llegó el plato y vio el Yorkshire pudding: una especie de cuenco dorado de masa, hueco por dentro. Lo miró como panadero. Lo tocó. Le dio unos golpecitos con la cuchara. «Esto es un pan que salió mal», dijo. Se lo comió entero. «Y está buenísimo.»",
      "Ihr Vater hörte »Pudding« und freute sich: ein Nachtisch. Dann kam der Teller, und er sah den Yorkshire Pudding: eine Art goldene Schale aus Teig, innen hohl. Er betrachtete ihn als Bäcker. Er fasste ihn an. Er klopfte mit dem Löffel darauf. »Das ist ein Brot, das schiefgegangen ist«, sagte er. Er aß ihn ganz auf. »Und es ist köstlich.«"),
    Z("—Is there something lighter? My mother and I would like to share.", "¿Hay algo más ligero? Mi madre y yo querríamos compartir.", "Gibt es etwas Leichteres? Meine Mutter und ich würden gern teilen."),
    Z("—The fish and chips, then. That's plenty for two.", "Entonces el fish and chips. Hay de sobra para dos.", "Dann Fish and Chips. Das reicht locker für zwei."),
    Z("—Perfect.", "Perfecto.", "Perfekt."),
    Z("It was plenty for two. It was nearly plenty for three. Mateo helped.", "Había de sobra para dos. Casi había de sobra para tres. Mateo ayudó.", "Es reichte locker für zwei. Es reichte fast für drei. Mateo half mit."),
    N("Al final llegó el momento difícil. Su padre ya tenía la cartera en la mano. En México, el padre paga. Siempre. Es casi una ley. Pero Sofía le puso la mano encima de la cartera. «Hoy no, papá. Hoy pago yo.»",
      "Am Ende kam der schwierige Moment. Ihr Vater hatte das Portemonnaie schon in der Hand. In Mexiko zahlt der Vater. Immer. Das ist fast ein Gesetz. Aber Sofía legte ihre Hand auf das Portemonnaie. »Heute nicht, Papa. Heute zahle ich.«"),
    Z("—Excuse me, could we have the bill, please?", "Perdone, ¿nos trae la cuenta, por favor?", "Entschuldigung, könnten wir bitte die Rechnung haben?"),
    Z("Dan raised his hand.", "Dan levantó la mano.", "Dan hob die Hand."),
    Z("—And would you mind splitting the check?", "¿Y le importaría dividir la cuenta?", "Und würde es Ihnen etwas ausmachen, die Rechnung aufzuteilen?"),
    Z("—Splitting the bill? Of course not. Here it's the bill, by the way, not the check. How many ways?", "¿Dividir la cuenta? Claro que no. Por cierto, aquí se dice «bill», no «check». ¿En cuántas partes?", "Die Rechnung aufteilen? Natürlich nicht. Hier sagt man übrigens »bill«, nicht »check«. In wie viele Teile?"),
    Z("—Two. Priya and Dan, and me. I'm paying for my family.", "En dos. Priya y Dan, y yo. Yo pago lo de mi familia.", "In zwei. Priya und Dan, und ich. Ich zahle für meine Familie."),
    N("Sofía pagó con su tarjeta inglesa. La tarjeta que le había costado un contrato de alquiler, un tren a Brighton, un capitán con pluma estilográfica y una gaviota. Era su sueldo. El primero que no se había gastado en el alquiler.",
      "Sofía zahlte mit ihrer englischen Karte. Mit der Karte, die sie einen Mietvertrag gekostet hatte, eine Zugfahrt nach Brighton, einen Kapitän mit Füllfederhalter und eine Möwe. Es war ihr Gehalt. Das erste, das nicht für die Miete draufgegangen war."),
    Z("—Is the tip included?", "¿La propina está incluida?", "Ist das Trinkgeld inbegriffen?"),
    Z("—The service is, yes. But the dog accepts tips.", "El servicio sí. Pero el perro acepta propinas.", "Die Bedienung schon. Aber der Hund nimmt Trinkgeld an."),
    N("Su padre no dijo nada. Pero se sentó más derecho, como se sienta un hombre cuando su hija paga la comida en otro país, en otro idioma, con su propio dinero.",
      "Ihr Vater sagte nichts. Aber er setzte sich aufrechter hin, so wie ein Mann sich hinsetzt, wenn seine Tochter in einem anderen Land, in einer anderen Sprache, mit ihrem eigenen Geld das Essen bezahlt."),
    Z("Then he leaned over and whispered something in Spanish. Sofía laughed and turned to the waiter.", "Luego se inclinó y le susurró algo en español. Sofía se rió y se volvió hacia el camarero.", "Dann beugte er sich zu ihr und flüsterte etwas auf Spanisch. Sofía lachte und drehte sich zum Kellner um."),
    Z("—Sorry, could I get a receipt? For my father's bakery.", "Perdone, ¿me puede dar un recibo? Para la panadería de mi padre.", "Entschuldigung, kann ich eine Quittung bekommen? Für die Bäckerei meines Vaters."),
    Z("The dog got a piece of Yorkshire pudding. Her father said it was for research.", "El perro se llevó un trozo de Yorkshire pudding. Su padre dijo que era para investigar.", "Der Hund bekam ein Stück Yorkshire Pudding. Ihr Vater sagte, das sei für die Forschung.")
  ]),

  // ── Station 19 · ARZT (A2) ──────────────────────────────────────────
  S('aufbau', 19, 'arzt', "It's got worse",
    "La acera está helada, el padre lleva una caja de conchas y se cae. Las conchas sobreviven. El hombro, más o menos.",
    "Der Gehweg ist vereist, der Vater trägt eine Kiste Conchas und stürzt. Die Conchas überleben. Die Schulter, so halbwegs.",
  [
    Z("On Sunday night it was very cold. On Monday morning, the pavement in front of the house was white and shiny.", "El domingo por la noche hizo mucho frío. El lunes por la mañana, la acera delante de la casa estaba blanca y brillante.", "In der Nacht zum Montag war es sehr kalt. Am Montagmorgen war der Gehweg vor dem Haus weiß und glänzend."),
    Z("Sofía's father came out of the door with a box of conchas. They were a present for Mrs Okafor.", "El padre de Sofía salió por la puerta con una caja de conchas. Eran un regalo para la señora Okafor.", "Sofías Vater kam mit einer Kiste Conchas aus der Tür. Sie waren ein Geschenk für Mrs Okafor."),
    Z("Dan shouted from the window:", "Dan gritó desde la ventana:", "Dan rief aus dem Fenster:"),
    Z("—Careful! The sidewalk is like ice!", "¡Cuidado! ¡La acera está como el hielo!", "Vorsicht! Der Gehweg ist wie Eis!"),
    Z("Priya corrected him:", "Priya lo corrigió:", "Priya korrigierte ihn:"),
    Z("—The pavement, Dan. Here it's the pavement.", "La «pavement», Dan. Aquí se dice «pavement».", "Das heißt »pavement«, Dan. Hier sagt man »pavement«."),
    Z("—Whatever it's called, it's slippery!", "¡Se llame como se llame, resbala!", "Egal, wie es heißt, es ist rutschig!"),
    N("Demasiado tarde. Su padre resbaló, dio una vuelta en el aire digna de un patinador y cayó sobre el hombro izquierdo. La caja, en cambio, aterrizó sobre su barriga, intacta. Lo había decidido en el aire: el hombro o las conchas.",
      "Zu spät. Ihr Vater rutschte aus, drehte sich in der Luft wie ein Eiskunstläufer und fiel auf die linke Schulter. Die Kiste dagegen landete unversehrt auf seinem Bauch. Er hatte es in der Luft entschieden: die Schulter oder die Conchas."),
    N("«No es nada», dijo. Lo dijo el lunes al mediodía, y lo dijo por la noche. El martes por la mañana ya no podía ni ponerse el jersey nuevo. Eso sí que era grave.",
      "»Das ist nichts«, sagte er. Er sagte es am Montagmittag, und er sagte es am Abend. Am Dienstagmorgen konnte er nicht einmal mehr den neuen Pullover anziehen. Das war nun wirklich ernst."),
    Z("At the GP surgery, the receptionist with the red glasses remembered Sofía from October.", "En el centro de salud, la recepcionista de las gafas rojas se acordaba de Sofía de octubre.", "In der Hausarztpraxis erinnerte sich die Empfangsdame mit der roten Brille an Sofía vom Oktober."),
    Z("—You again! Do you have your proof of address this time?", "¡Usted otra vez! ¿Esta vez trae el justificante de domicilio?", "Sie schon wieder! Haben Sie diesmal Ihren Wohnsitznachweis dabei?"),
    Z("Sofía went white. The receptionist laughed.", "Sofía se puso blanca. La recepcionista se rió.", "Sofía wurde blass. Die Empfangsdame lachte."),
    Z("—Just joking, love. Take a seat in the waiting room.", "Es broma, cariño. Siéntense en la sala de espera.", "Nur ein Scherz, meine Liebe. Setzen Sie sich ins Wartezimmer."),
    N("En la sala de espera, su padre sacó un papelito del bolsillo. Mateo le había escrito una frase en inglés. Esta vez Sofía la leyó antes. Era correcta. Casi le dio pena.",
      "Im Wartezimmer zog ihr Vater einen Zettel aus der Tasche. Mateo hatte ihm einen englischen Satz aufgeschrieben. Diesmal las Sofía ihn vorher. Er war korrekt. Fast war sie enttäuscht."),
    Z("—Have a seat. So what happened?", "Siéntense. A ver, ¿qué ha pasado?", "Setzen Sie sich. Also, was ist passiert?"),
    Z("—My father fell yesterday, and his shoulder has got worse.", "Mi padre se cayó ayer y el hombro le ha empeorado.", "Mein Vater ist gestern gestürzt, und seine Schulter ist schlimmer geworden."),
    Z("—Is he taking anything right now?", "¿Está tomando algo ahora mismo?", "Nimmt er gerade etwas?"),
    Z("—Just painkillers. And he's allergic to—", "Solo analgésicos. Y es alérgico a…", "Nur Schmerzmittel. Und er ist allergisch gegen …"),
    Z("Her father raised his good hand. He wanted to say it himself. He had practised in the waiting room.", "Su padre levantó la mano buena. Quería decirlo él. Lo había practicado en la sala de espera.", "Ihr Vater hob die gesunde Hand. Er wollte es selbst sagen. Er hatte im Wartezimmer geübt."),
    Z("—I am allergic to penicillin. And I am very handsome.", "Soy alérgico a la penicilina. Y soy muy guapo.", "Ich bin allergisch gegen Penicillin. Und ich bin sehr gutaussehend."),
    Z("The doctor wrote something down.", "La médica apuntó algo.", "Die Ärztin schrieb etwas auf."),
    Z("—Both noted.", "Anotadas las dos cosas.", "Beides notiert."),
    Z("—Let's get an X-ray and go from there.", "Vamos a hacerle una radiografía y luego ya vemos.", "Machen wir ein Röntgenbild und sehen dann weiter."),
    Z("An hour later, the doctor looked at the X-ray.", "Una hora después, la médica miró la radiografía.", "Eine Stunde später sah sich die Ärztin das Röntgenbild an."),
    Z("—Good news. Nothing is broken. It's a bad bruise. He needs a sling for a week, and rest.", "Buenas noticias. No hay nada roto. Es un golpe fuerte. Necesita un cabestrillo durante una semana, y reposo.", "Gute Nachrichten. Nichts ist gebrochen. Es ist eine schwere Prellung. Er braucht eine Woche lang eine Armschlinge und Ruhe."),
    Z("—Rest? He's a baker. He doesn't know the word.", "¿Reposo? Es panadero. No conoce esa palabra.", "Ruhe? Er ist Bäcker. Das Wort kennt er nicht."),
    Z("—Then you'll have to teach him. Your English is very good.", "Pues tendrá que enseñársela usted. Su inglés es muy bueno.", "Dann müssen Sie es ihm beibringen. Ihr Englisch ist sehr gut."),
    N("En el autobús de vuelta, su padre le hizo preguntas en voz baja. «¿Puedo amasar?» — «No.» — «¿Con la otra mano?» — «Papá.» — «¿Y mirar cómo amasa otro?» — «Eso sí.» Se quedó tranquilo.",
      "Im Bus auf dem Rückweg stellte ihr Vater leise Fragen. »Darf ich Teig kneten?« – »Nein.« – »Mit der anderen Hand?« – »Papa.« – »Und zusehen, wie ein anderer knetet?« – »Das schon.« Damit war er zufrieden."),
    Z("The conchas were fine. Not one was broken. Mrs Okafor ate two at once.", "Las conchas estaban bien. Ni una rota. La señora Okafor se comió dos de golpe.", "Den Conchas ging es gut. Keine einzige war zerbrochen. Mrs Okafor aß zwei auf einmal."),
    Z("—Tell your father he fell well. The pigeons saw everything. They were very impressed.", "Dile a tu padre que se cayó bien. Las palomas lo vieron todo. Quedaron muy impresionadas.", "Sag deinem Vater, er ist gut gefallen. Die Tauben haben alles gesehen. Sie waren sehr beeindruckt.")
  ]),

  // ── Station 20 · FAMILIE (A2) ───────────────────────────────────────
  S('aufbau', 20, 'familie', "Where did you grow up?",
    "Navidad en el piso de Kentish Town: todos vienen, todos cuentan de dónde son. Y Sofía descubre que en inglés se echa de menos como se pierde un tren.",
    "Weihnachten in der Wohnung in Kentish Town: Alle kommen, alle erzählen, woher sie kommen. Und Sofía entdeckt, dass man auf Englisch jemanden vermisst, wie man einen Zug verpasst.",
  [
    Z("On Christmas Day, the small flat in Kentish Town was full. It was the family's last evening in London.", "El día de Navidad, el piso pequeño de Kentish Town estaba lleno. Era la última noche de la familia en Londres.", "Am ersten Weihnachtstag war die kleine Wohnung in Kentish Town voll. Es war der letzte Abend der Familie in London."),
    Z("Everyone came. Mrs Okafor brought a Christmas cake and the weather forecast.", "Vino todo el mundo. La señora Okafor trajo un pastel de Navidad y el parte meteorológico.", "Alle kamen. Mrs Okafor brachte einen Weihnachtskuchen und die Wettervorhersage mit."),
    Z("Mrs Georgiou closed the café for the first time in years and brought a lemon cake.", "La señora Georgiou cerró el café por primera vez en años y trajo una tarta de limón.", "Mrs Georgiou schloss zum ersten Mal seit Jahren ihr Café und brachte einen Zitronenkuchen mit."),
    Z("Mr Ade from the market brought a huge Stilton and a letter. Del brought a bottle, and he held his cap in his hand all evening.", "El señor Ade, del mercado, trajo un Stilton enorme y una carta. Del trajo una botella y tuvo la gorra en la mano toda la noche.", "Mr Ade vom Markt brachte einen riesigen Stilton und einen Brief mit. Del brachte eine Flasche und hielt den ganzen Abend seine Mütze in der Hand."),
    Z("The letter was from Captain Clarke, in Brighton. A real letter, in an envelope, of course.", "La carta era del capitán Clarke, de Brighton. Una carta de verdad, en un sobre, claro.", "Der Brief war von Kapitän Clarke aus Brighton. Ein echter Brief, in einem Umschlag, natürlich."),
    Z("“To Miss Herrera and family. Merry Christmas. Fair winds. — D. Clarke.” Under his name, he had drawn a little ship.", "«Para la señorita Herrera y familia. Feliz Navidad. Buenos vientos. — D. Clarke.» Debajo de su nombre había dibujado un barquito.", "»An Miss Herrera und Familie. Frohe Weihnachten. Guten Wind. – D. Clarke.« Unter seinen Namen hatte er ein kleines Schiff gezeichnet."),
    N("Su madre había hecho pozole en una cocina inglesa, con ingredientes de tres tiendas distintas y la ayuda de Priya, que sabía dónde comprar chiles en Londres. Su padre, con el brazo en cabestrillo, lo vigilaba todo y no tocaba nada. Le costaba muchísimo.",
      "Ihre Mutter hatte in einer englischen Küche Pozole gekocht, mit Zutaten aus drei verschiedenen Läden und mit Priyas Hilfe, die wusste, wo man in London Chilis kauft. Ihr Vater, den Arm in der Schlinge, überwachte alles und fasste nichts an. Das fiel ihm unendlich schwer."),
    Z("After dinner, Del sat down next to Sofía.", "Después de cenar, Del se sentó al lado de Sofía.", "Nach dem Essen setzte sich Del neben Sofía."),
    Z("—So where did you grow up, anyway?", "Bueno, ¿y tú dónde te criaste?", "Und wo bist du eigentlich aufgewachsen?"),
    Z("—In a small town in Jalisco. Near a lake.", "En un pueblo pequeño de Jalisco. Cerca de un lago.", "In einem kleinen Ort in Jalisco. In der Nähe eines Sees."),
    Z("—Was the whole family out there?", "¿Estaba toda la familia allí?", "War die ganze Familie dort?"),
    Z("—Yes. On Sundays we'd all meet at my aunt's place. Aunt Chayo. Cousins, uncles, grandparents. Thirty people and one very small kitchen.", "Sí. Los domingos nos reuníamos todos en casa de mi tía. La tía Chayo. Primos, tíos, abuelos. Treinta personas y una cocina muy pequeña.", "Ja. Sonntags trafen wir uns alle bei meiner Tante. Tante Chayo. Cousins, Onkel, Großeltern. Dreißig Leute und eine sehr kleine Küche."),
    Z("—Are they still around?", "¿Siguen allí?", "Sind sie noch dort?"),
    Z("—Most of them. But I moved away. First to Mexico City, then here. I miss them.", "Casi todos. Pero yo me fui. Primero a Ciudad de México, después aquí. Los echo de menos.", "Die meisten. Aber ich bin weggezogen. Erst nach Mexiko-Stadt, dann hierher. Ich vermisse sie."),
    Z("Del nodded slowly.", "Del asintió despacio.", "Del nickte langsam."),
    Z("—I grew up three streets from here. I never moved away. And I still miss it. It's not the same street any more.", "Yo me crié a tres calles de aquí. Nunca me fui. Y aun así lo echo de menos. Ya no es la misma calle.", "Ich bin drei Straßen von hier aufgewachsen. Ich bin nie weggezogen. Und trotzdem vermisse ich es. Es ist nicht mehr dieselbe Straße."),
    N("Entonces todos empezaron a contar. La señora Georgiou, su pueblo en Chipre, con limoneros y una sola cabina de teléfono. La señora Okafor, Enugu, y una abuela que predecía la lluvia mirando las gallinas. «¿Ves?», dijo, «viene de familia». Priya tradujo para la madre de Sofía; Sofía, para su padre; Mateo, para nadie: ya entendía bastante.",
      "Dann begannen alle zu erzählen. Mrs Georgiou von ihrem Dorf auf Zypern, mit Zitronenbäumen und einer einzigen Telefonzelle. Mrs Okafor von Enugu und einer Großmutter, die den Regen an den Hühnern ablas. »Siehst du?«, sagte sie, »das liegt in der Familie.« Priya übersetzte für Sofías Mutter, Sofía für ihren Vater, Mateo für niemanden: Er verstand inzwischen genug."),
    Z("At the end, Dan played his guitar. Her father sang with him, one arm in a sling. Mrs Okafor's pigeons listened at the window.", "Al final, Dan tocó la guitarra. Su padre cantó con él, con un brazo en cabestrillo. Las palomas de la señora Okafor escuchaban en la ventana.", "Zum Schluss spielte Dan Gitarre. Ihr Vater sang mit, einen Arm in der Schlinge. Die Tauben von Mrs Okafor hörten am Fenster zu."),
    Z("The next morning, Del's black cab was waiting in front of the house. Sofía had not called him. He was just there.", "A la mañana siguiente, el taxi negro de Del esperaba delante de la casa. Sofía no lo había llamado. Simplemente estaba allí.", "Am nächsten Morgen wartete Dels schwarzes Taxi vor dem Haus. Sofía hatte ihn nicht gerufen. Er war einfach da."),
    N("Despedidas en la acera, que esta vez no resbalaba. Su madre la abrazó demasiado tiempo. Su padre le dio un abrazo con un solo brazo, que con él valía por dos. Mateo le dijo, en inglés: «See you, sister.» Lo había ensayado. Esta vez, sin trampa.",
      "Abschied auf dem Gehweg, der diesmal nicht rutschig war. Ihre Mutter umarmte sie zu lange. Ihr Vater umarmte sie mit einem einzigen Arm, was bei ihm für zwei zählte. Mateo sagte auf Englisch: »See you, sister.« Er hatte es geübt. Diesmal ohne Trick."),
    Z("Then the street was empty, and the flat was very quiet.", "Después, la calle se quedó vacía, y el piso, muy silencioso.", "Dann war die Straße leer, und in der Wohnung war es sehr still."),
    N("En español, a alguien se le echa de menos: notas un hueco, como una cuenta que no sale. En inglés se dice «to miss», la misma palabra que en Slough. Pierdes un tren por un minuto y te quedas en el andén, mirando cómo se va.",
      "Auf Deutsch vermisst man jemanden: Man spürt eine Lücke. Auf Englisch sagt man »to miss«, dasselbe Wort wie in Slough. Man verpasst einen Zug um eine Minute und bleibt auf dem Bahnsteig stehen und sieht ihm nach."),
    Z("Sofía missed them. Like a train.", "Sofía los echaba de menos. Como quien pierde un tren.", "Sofía vermisste sie. Wie einen verpassten Zug."),
    N("Pero en ese andén había aprendido algo más.",
      "Aber auf diesem Bahnsteig hatte sie noch etwas gelernt."),
    Z("There is always a next train. And your ticket is still valid.", "Siempre hay un tren siguiente. Y tu billete sigue siendo válido.", "Es gibt immer einen nächsten Zug. Und deine Fahrkarte bleibt gültig.")
  ]),

  // ── Station 21 · EPILOG · ANWENDUNG ─────────────────────────────────
  S('anwendung', 21, null, "Cheers",
    "Junio. Sofía se queda en Londres, pero Priya se va a Edimburgo. Una última semana, un último té, y una palabra inglesa que dice tres cosas a la vez. Todo en inglés.",
    "Juni. Sofía bleibt in London, aber Priya zieht nach Edinburgh. Eine letzte Woche, ein letzter Tee und ein englisches Wort, das drei Dinge auf einmal sagt. Ganz auf Englisch.",
  [
    P("June came to London slowly, and then all at once. One Monday it was still cold enough for a jumper; on Tuesday the parks were full of people lying on the grass as if they had never seen the sun before."),
    P("Sofía had good news. The publisher had renewed her contract for two more years. Her boss had put the letter on her desk next to a slice of lemon cake and said only, “We'd be very sorry to lose you.” In London, Sofía now knew, that was almost a declaration of love."),
    P("But the news in the flat was not only hers. Priya was leaving. A company in Edinburgh had offered her a job, a bigger salary and a view of a castle from her new office. She had said yes in March. In May she had “preponed” her start date by two weeks."),
    P("“Preponed?” said Dan, the first time he heard it."),
    P("“The opposite of postponed,” Priya said. “It's Indian English. It's a perfectly logical word. The rest of the world is just slow.”"),
    P("Now the flat was full of boxes. Priya had labelled every one of them in three colours. Dan had labelled one box himself. It said STUFF."),
    P("On Wednesday morning, Sofía and Priya went to Mrs Georgiou's café together. Mrs Georgiou did not ask what they wanted. She put two teas on the table, both with milk, and a plate with two pieces of lemon cake."),
    P("“For the one who is leaving,” she said, “and for the one who is staying. You decide who is who.”"),
    P("She did not take their money. When Priya tried to pay, Mrs Georgiou looked at her for exactly three seconds, the way she had once looked at Dan, and Priya put her purse away."),
    P("On Thursday they went to Borough Market. Mr Ade wrapped a piece of Scottish cheese in paper and gave it to Priya."),
    P("“So you don't feel homesick for London cheese up there,” he said. “Tell the Scots that Ade sent you.”"),
    P("He also had news. Captain Clarke had written again, a real letter, of course. He wanted Sofía to design his memoirs: forty years at sea, three hundred pages, all handwritten with the old fountain pen. “He doesn't trust e-mail,” Mr Ade said, “but he trusts you.” Sofía decided this was the best compliment of her career."),
    P("On Friday, the last evening, there was a small party in the kitchen. Dan played a song he had written for Priya. It had three chords and one rhyme, “Edinburgh” with “thorough”, and everybody agreed that it was a very good song."),
    P("At ten o'clock, Mrs Okafor knocked on the door. She had come to give Priya the weather forecast for Scotland."),
    P("“I asked the pigeons,” she said. “They say it will rain in Edinburgh.”"),
    P("“When?” asked Priya."),
    P("“Always, darling. But you will have a very good umbrella. I have bought it for you.”"),
    P("It was purple, and it was enormous. Priya opened it in the kitchen, which everybody knew was bad luck, and nobody cared."),
    P("Later, when the others had gone to bed, Sofía and Priya sat by the open window. A fox walked past under the lamp and did not stop."),
    P("“Do you remember your first evening?” Priya asked. “You stood at the door with your suitcase, completely wet. One week later you were saying sorry to the furniture. That's when I knew you would be fine here.”"),
    P("Sofía laughed. She remembered the rain, the black cab, the word “boot”, and the e-mail about “proof of address”. She had thought London wanted papers from her. Now she knew it wanted something else: patience, a little humour, and the ability to stand in a queue without complaining."),
    P("On Saturday morning, a black cab was waiting outside the house. Nobody had called it. Del was leaning against the door with his cap on and the radio talking about cricket."),
    P("“Mrs Georgiou told me,” Del said. He put Priya's suitcase and her last two boxes inside the cab, next to the seats, as if they were empty. Even the one that said STUFF. Then he winked at Sofía. “No boot in a black cab, love. Never was.”"),
    P("They drove to King's Cross. Del went the long way, slowly, through streets Sofía now knew by heart: past the café, past the blue door of her office in Bloomsbury, past the corner where two Texans had once turned the wrong way. London was still big. But some of it was hers now."),
    P("At the station, Del stopped the meter. Priya took out her purse."),
    P("“Put that away, love,” Del said. “This one's on me. Just send us some decent weather.”"),
    P("On the platform, the train to Edinburgh was waiting, on time, which Priya said was a good sign and Sofía said was a miracle. They hugged, and then they hugged again, because the first one had been too short."),
    P("Priya got on the train. She turned at the door and looked at Sofía. She wanted to say many things: thank you for the year, goodbye, good luck with the Captain's book, look after Dan, don't let him label any more boxes. There was no time for all of that. So she said the one word that does all of it."),
    P("“Cheers, Sofía.”"),
    P("Sofía smiled. When she first arrived, she thought “cheers” was something you said with a glass in your hand. Then she heard it on buses, in shops, from Del and from strangers, and she slowly understood. In Britain it means thank you. It means goodbye. It means good luck. Often all three at once, and nobody has to choose."),
    P("“Cheers, Priya.”"),
    P("The doors closed. The train left on time. And Sofía, standing on the platform, did not feel that she had missed anything at all.")
  ])

  ];
})(window);

